import React, { useState, MouseEvent } from 'react';
import { PortfolioItem } from '../App';
import PortfolioModal from './PortfolioModal';
import SearchIcon from './icons/SearchIcon';
import CarouselMediaItem from './CarouselMediaItem';

interface HeroProps {
  portfolioData: PortfolioItem[];
  onNavigate: (view: 'home' | 'admin') => void;
  heroTattooGunImageUrl: string;
}

const Hero: React.FC<HeroProps> = ({ portfolioData, onNavigate, heroTattooGunImageUrl }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedItem, setSelectedItem] = useState<PortfolioItem | null>(null);

  const handleImageClick = (item: PortfolioItem) => {
    setSelectedItem(item);
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    // Delay clearing the item to allow for the closing animation
    setTimeout(() => setSelectedItem(null), 500);
  };

  const handleLinkClick = (e: MouseEvent<HTMLAnchorElement>) => {
    e.preventDefault();
    const href = e.currentTarget.getAttribute('href');
    if (!href) return;

    if (href.startsWith('#')) {
      document.querySelector(href)?.scrollIntoView({ behavior: 'smooth' });
    }
  };

  const featuredItems = portfolioData.filter(item => item.featured);
  // Use featured items if available, otherwise fall back to the first 6 portfolio items to ensure the carousel is not empty.
  const itemsForCarousel = featuredItems.length > 0 ? featuredItems : portfolioData.slice(0, 6);
  // Duplicate the array for a seamless infinite scroll effect
  const allPortfolioItems = itemsForCarousel.length > 0 ? [...itemsForCarousel, ...itemsForCarousel] : [];


  return (
    <>
      <section className="relative h-screen bg-brand-dark text-brand-light overflow-hidden">

        {/* Light Mode Gradient */}
        <div className="absolute top-0 left-0 w-full h-full z-0 bg-gradient-to-t from-white via-white/70 to-transparent"></div>

        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-[55%] z-20 w-full text-center px-4">
          <div className="relative">
            <img 
                src={heroTattooGunImageUrl}
                alt="Nail Polish"
                aria-hidden="true"
                className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[18rem] sm:w-[25rem] md:w-[30rem] lg:w-[35rem] max-w-none h-auto opacity-10 lg:opacity-15 transform rotate-[15deg] pointer-events-none filter sepia-[.3] contrast-[0.9]"
            />
            <h1 
              className="relative z-10 font-script text-5xl sm:text-7xl md:text-8xl lg:text-9xl leading-tight tracking-wide text-brand-light"
              style={{
                  textShadow: `0px 2px 4px rgba(0,0,0,0.1)`
              }}
            >
              Natural beauty, polished to perfection.
            </h1>
            <p className="relative z-10 mt-6 max-w-xl mx-auto text-gray-600 text-base sm:text-lg tracking-wider uppercase font-semibold">
              Step into the wild. Experience premium nail care in a serene, nature-inspired setting.
            </p>
            <div className="relative z-10 mt-8 flex flex-col sm:flex-row items-center justify-center gap-4">
