import React, { useState, useEffect } from 'react';
import { db, auth } from './firebase';
import { collection, doc, setDoc, addDoc, updateDoc, deleteDoc, writeBatch, onSnapshot } from 'firebase/firestore';
import { onAuthStateChanged, User } from 'firebase/auth';

import Header from './components/Header';
import Hero from './components/Hero';
import SpecialsCollage from './components/SpecialsCollage';
import ContactForm from './components/ContactForm';
import Footer from './components/Footer';
import AdminPage from './pages/AdminPage';
import Showroom from './pages/ShowroomPage';
import AboutUs from './components/AboutUs';
import WelcomeIntro from './components/WelcomeIntro';
import MaintenancePage from './components/MaintenancePage';

// --- INTERFACES (Unchanged) ---
export interface PortfolioItem {
  id: string;
  title: string;
  story: string;
  primaryImage: string;
  galleryImages: string[];
  videoData?: string;
  featured?: boolean;
}
export interface ShowroomItem {
  id: string;
  title: string;
  images: string[];
  videoUrl?: string;
}
export interface SpecialItem {
  id: string;
  title: string;
  description: string;
  imageUrl: string;
  priceType: 'hourly' | 'fixed' | 'percentage' | 'none';
  priceValue?: number;
  details: string[];
  voucherCode?: string;
}
export interface SocialLink {
  id: string;
  url: string;
  icon: string;
}
export interface Booking {
  id: string;
  name: string;
  email: string;
  whatsappNumber?: string;
  contactMethod?: 'email' | 'whatsapp';
  message: string;
  bookingDate: string;
  status: 'pending' | 'confirmed' | 'completed' | 'cancelled';
  bookingType: 'online' | 'manual';
  totalCost?: number;
  amountPaid?: number;
  paymentMethod?: 'cash' | 'card' | 'transfer' | 'other';
  referenceImages?: string[];
}
export interface Genre {
  id:string;
  name: string;
  items: ShowroomItem[];
}
export interface Expense {
  id: string;
  date: string;
  category: 'Supplies' | 'Rent' | 'Utilities' | 'Marketing' | 'Other';
  description: string;
  amount: number;
}
export interface InventoryItem {
  id: string;
  name: string;
  category: string;
  quantity: number;
  cost: number;
  supplier?: string;
  brand?: string;
  lotNumber?: string;
}

// --- MAIN APP COMPONENT ---
const App: React.FC = () => {
  // --- STATE ---
  const [user, setUser] = useState<User | null>(null);
  const [authChecked, setAuthChecked] = useState(false);
  const [loading, setLoading] = useState(true);
  const [dataError, setDataError] = useState<string | null>(null);

  const [portfolioData, setPortfolioData] = useState<PortfolioItem[]>([]);
  const [specialsData, setSpecialsData] = useState<SpecialItem[]>([]);
  const [showroomData, setShowroomData] = useState<Genre[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [inventory, setInventory] = useState<InventoryItem[]>([]);

  // Site settings state with updated defaults for Bos Salon
  const [companyName, setCompanyName] = useState('Bos Salon');
  const [logoUrl, setLogoUrl] = useState('https://i.ibb.co/gLSThX4v/unnamed-removebg-preview.png'); // Updated Logo
  const [aboutUsImageUrl, setAboutUsImageUrl] = useState('https://picsum.photos/seed/nail-artist/500/500');
  const [whatsAppNumber, setWhatsAppNumber] = useState('27795904162');
  const [address, setAddress] = useState('123 Nature Way, Green Valley, 45678');
  const [phone, setPhone] = useState('+27 12 345 6789');
  const [email, setEmail] = useState('bookings@bossalon.com');
  const [socialLinks, setSocialLinks] = useState<SocialLink[]>([]);
  const [showroomTitle, setShowroomTitle] = useState('Nail Art Gallery');
  const [showroomDescription, setShowroomDescription] = useState("Browse our collection of hand-painted designs and natural treatments.");
  const [heroTattooGunImageUrl, setHeroTattooGunImageUrl] = useState('https://cdn-icons-png.flaticon.com/512/3756/3756854.png'); // Default to a nail polish icon/image
  const [bankName, setBankName] = useState('FNB');
  const [accountNumber, setAccountNumber] = useState('1234567890');
  const [branchCode, setBranchCode] = useState('250655');
  const [accountType, setAccountType] = useState('Cheque');
  const [vatNumber, setVatNumber] = useState('');
  const [isMaintenanceMode, setIsMaintenanceMode] = useState(false);
  const [apkUrl, setApkUrl] = useState('');

  const [currentView, setCurrentView] = useState('home');
  const [isIntroVisible, setIsIntroVisible] = useState(true);

  // --- AUTH STATE LISTENER ---
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setAuthChecked(true);
    });
    return () => unsubscribe();
  }, []);

  // --- PUBLIC DATA FETCHING ---
  useEffect(() => {
    const unsubscribers: (() => void)[] = [];
    let isMounted = true;

    try {
      // Subscribe to settings document
      const settingsUnsub = onSnapshot(doc(db, "settings", "main"), (doc) => {
        if (doc.exists() && isMounted) {
          const settings = doc.data();
          setCompanyName(settings.companyName);
          setLogoUrl(settings.logoUrl);
          setAboutUsImageUrl(settings.aboutUsImageUrl);
          setWhatsAppNumber(settings.whatsAppNumber);
          setAddress(settings.address);
          setPhone(settings.phone);
          setEmail(settings.email);
          setSocialLinks(settings.socialLinks);
          setShowroomTitle(settings.showroomTitle);
          setShowroomDescription(settings.showroomDescription);
          setHeroTattooGunImageUrl(settings.heroTattooGunImageUrl);
          setBankName(settings.bankName);
          setAccountNumber(settings.accountNumber);
          setBranchCode(settings.branchCode);
          setAccountType(settings.accountType);
          setVatNumber(settings.vatNumber);
          setIsMaintenanceMode(settings.isMaintenanceMode ?? false);
          setApkUrl(settings.apkUrl ?? '');
        }
      }, (error) => {
        console.error("Error listening to settings:", error);
        if(isMounted) setDataError("Failed to load critical site settings. This is likely a Firestore security rule issue. Please ensure the 'settings' collection is publicly readable.");
      });
      unsubscribers.push(settingsUnsub);

      // Subscribe to public collections
      const publicCollections: { name: string, setter: React.Dispatch<React.SetStateAction<any[]>> }[] = [
        { name: 'portfolio', setter: setPortfolioData },
        { name: 'specials', setter: setSpecialsData },
        { name: 'showroom', setter: setShowroomData },
      ];

      publicCollections.forEach(({ name, setter }) => {
        const unsub = onSnapshot(collection(db, name), (snapshot) => {
          if (isMounted) setter(snapshot.docs.map(d => ({ id: d.id, ...d.data() })));
        }, (error) => {
          console.error(`Error listening to public collection ${name}:`, error);
          if (isMounted) setDataError(`Failed to load data for '${name}'. This is likely due to a Firestore security rule misconfiguration. Please ensure the '${name}' collection is publicly readable.`);
        });
        unsubscribers.push(unsub);
      });

    } catch (error) {
      console.error("Error setting up public Firestore listeners:", error);
      if (isMounted) setDataError("A critical error occurred while trying to connect to the database.");
    }

    return () => {
      isMounted = false;
      unsubscribers.forEach(unsub => unsub());
    };
  }, []);

  // --- PRIVATE (ADMIN) DATA FETCHING ---
  useEffect(() => {
    if (!user) {
      setBookings([]);
      setExpenses([]);
      setInventory([]);
      return;
    }

    // User is authenticated, fetch private data.
    const unsubscribers: (() => void)[] = [];
    let isMounted = true;
    try {
      const privateCollections: { name: string, setter: React.Dispatch<React.SetStateAction<any[]>> }[] = [
        { name: 'bookings', setter: setBookings },
        { name: 'expenses', setter: setExpenses },
        { name: 'inventory', setter: setInventory },
      ];

      privateCollections.forEach(({ name, setter }) => {
        const unsub = onSnapshot(collection(db, name), (snapshot) => {
          if (isMounted) setter(snapshot.docs.map(d => ({ id: d.id, ...d.data() })));
        }, (error) => {
            console.error(`Error listening to private collection ${name}:`, error);
            if (isMounted) setDataError(`Failed to load private data for '${name}'. Your account may not have the correct permissions.`);
        });
        unsubscribers.push(unsub);
      });
    } catch (error) {
      console.error("Error setting up private Firestore listeners:", error);
      if (isMounted) setDataError("A critical error occurred while trying to load administrator data.");
    }

    return () => {
      isMounted = false;
      unsubscribers.forEach(unsub => unsub());
    };
  }, [user]); // This effect depends on the user's auth state.

  // --- LOADING STATE ---
  useEffect(() => {
    if (authChecked) {
      setLoading(false);
    }
  }, [authChecked]);


  // --- INTRO & NAVIGATION ---
  useEffect(() => {
    if (sessionStorage.getItem('introShown')) {
      setIsIntroVisible(false);
    }
  }, []);

  const handleEnter = () => {
    sessionStorage.setItem('introShown', 'true');
    setIsIntroVisible(false);
  };

  const navigate = (view: 'home' | 'admin') => setCurrentView(view);

  const handleLogoutSuccess = () => {
    setUser(null); // Explicitly clear the user state for an immediate UI update
    navigate('home');
  };

  // --- CRUD (Create, Read, Update, Delete) FUNCTIONS ---

  // Generic update DB doc
  const updateItem = async <T extends {id: string}>(collectionName: string, item: T) => {
    try {
      const { id, ...data } = item;
      await updateDoc(doc(db, collectionName, id), data);
    } catch (error) {
      console.error(`Error updating ${collectionName}:`, error);
      alert(`Failed to update item in ${collectionName}. Please check the console for details and verify your Firestore security rules.`);
    }
  };

  // Generic add DB doc
  const addItem = async <T extends {}>(collectionName: string, item: T) => {
    try {
      await addDoc(collection(db, collectionName), item);
    } catch (error) {
      console.error(`Error adding ${collectionName}:`, error);
      alert(`Failed to add item to ${collectionName}. Please check the console for details and verify your Firestore security rules.`);
    }
  };

  // Generic delete DB doc
  const deleteItem = async (collectionName: string, itemId: string) => {
    try {
      await deleteDoc(doc(db, collectionName, itemId));
    } catch (error) {
      console.error(`Error deleting ${collectionName}:`, error);
      alert(`Failed to delete item from ${collectionName}. Please check the console for details and verify your Firestore security rules.`);
    }
  };

  // Portfolio
  const handleUpdatePortfolioItem = async (item: PortfolioItem) => await updateItem('portfolio', item);
  const handleAddPortfolioItem = async (item: Omit<PortfolioItem, 'id'>) => await addItem('portfolio', item);
  const handleDeletePortfolioItem = async (itemId: string) => await deleteItem('portfolio', itemId);

  // Specials
  const handleUpdateSpecialItem = async (item: SpecialItem) => await updateItem('specials', item);
  const handleAddSpecialItem = async (item: Omit<SpecialItem, 'id'>) => await addItem('specials', item);
  const handleDeleteSpecialItem = async (itemId: string) => await deleteItem('specials', itemId);

  // Showroom
  const handleUpdateShowroomGenre = async (item: Genre) => await updateItem('showroom', item);
  const handleAddShowroomGenre = async (item: Omit<Genre, 'id'>) => await addItem('showroom', item);
  const handleDeleteShowroomGenre = async (itemId: string) => await deleteItem('showroom', itemId);

  // Bookings
  const handleAddBooking = async (newBookingData: Omit<Booking, 'id' | 'status' | 'bookingType'>) => {
    const newBooking: Omit<Booking, 'id'> = {
      ...newBookingData,
      status: 'pending',
      bookingType: 'online',
    };
    await addItem('bookings', newBooking);
  };
  const handleManualAddBooking = async (newBookingData: Omit<Booking, 'id' | 'bookingType'>) => {
    const newBooking: Omit<Booking, 'id'> = {
      ...newBookingData,
      bookingType: 'manual',
    };
    await addItem('bookings', newBooking);
  };
  const handleUpdateBooking = async (item: Booking) => await updateItem('bookings', item);

  // Expenses
  const handleAddExpense = async (newExpense: Omit<Expense, 'id'>) => await addItem('expenses', newExpense);
  const handleUpdateExpense = async (updatedExpense: Expense) => await updateItem('expenses', updatedExpense);
  const handleDeleteExpense = async (expenseId: string) => await deleteItem('expenses', expenseId);

  // Inventory
  const handleAddInventoryItem = async (newItem: Omit<InventoryItem, 'id'>) => await addItem('inventory', newItem);
  const handleUpdateInventoryItem = async (updatedItem: InventoryItem) => await updateItem('inventory', updatedItem);
  const handleDeleteInventoryItem = async (itemId: string) => await deleteItem('inventory', itemId);

  // Settings
  const handleSaveAllSettings = async (settings: any) => {
    try {
        await setDoc(doc(db, "settings", "main"), settings, { merge: true });
    } catch (error) {
        console.error("Error saving settings:", error);
        alert("Failed to save settings. Please check the console for details and verify your Firestore security rules.");
    }
  };

  const handleClearAllData = async () => {
      if (!window.confirm("ARE YOU SURE? This will delete ALL content from your live database. This is irreversible.")) return;

      const collectionsToDelete = ['portfolio', 'specials', 'showroom', 'bookings', 'expenses', 'inventory'];
      const batch = writeBatch(db);

      try {
          for (const collectionName of collectionsToDelete) {
              const querySnapshot = await collection(db, collectionName).get();
              querySnapshot.docs.forEach(d => batch.delete(d.ref));
          }
          await batch.commit();

          alert('All live data has been cleared from the database.');
      } catch (error) {
          console.error("Error clearing data:", error);
          alert("An error occurred while clearing data. Check console for details.");
      }
  };

  // --- RENDER LOGIC ---

  if (loading) {
    return (
      <div className="fixed inset-0 z-[100] flex flex-col items-center justify-center bg-brand-dark">
         <img src={logoUrl || "https://i.ibb.co/gLSThX4v/unnamed-removebg-preview.png"} alt="Bos Salon Logo" className="w-48 h-48 object-contain animate-pulse"/>
         <p className="text-brand-light/70 mt-4">Opening Salon...</p>
      </div>
    );
  }

  if (dataError) {
    return (
        <div className="fixed inset-0 z-[100] flex flex-col items-center justify-center bg-brand-dark text-brand-light p-8 text-center">
            <div className="max-w-2xl">
                <h1 className="text-2xl font-bold text-red-500 mb-4">🚨 Application Error</h1>
                <p className="mb-4">A critical error occurred while fetching data from the database:</p>
                <p className="font-mono bg-black/10 p-4 rounded-lg text-red-500 text-left text-sm whitespace-pre-wrap">{dataError}</p>
                <p className="mt-6 text-gray-500 text-sm">This usually means the database security rules in your Firebase project are not configured correctly. Please update your rules in the Firebase Console and then refresh this page.</p>
            </div>
        </div>
    );
  }

  if (currentView === 'admin') {
    return (
      <AdminPage
        user={user}
        onNavigate={navigate}
        portfolioData={portfolioData}
        onAddPortfolioItem={handleAddPortfolioItem}
        onUpdatePortfolioItem={handleUpdatePortfolioItem}
        onDeletePortfolioItem={handleDeletePortfolioItem}
        specialsData={specialsData}
        onAddSpecialItem={handleAddSpecialItem}
        onUpdateSpecialItem={handleUpdateSpecialItem}
        onDeleteSpecialItem={handleDeleteSpecialItem}
        showroomData={showroomData}
        onAddShowroomGenre={handleAddShowroomGenre}
        onUpdateShowroomGenre={handleUpdateShowroomGenre}
        onDeleteShowroomGenre={handleDeleteShowroomGenre}
        bookings={bookings}
        onUpdateBooking={handleUpdateBooking}
        onManualAddBooking={handleManualAddBooking}
        expenses={expenses}
        onAddExpense={handleAddExpense}
        onUpdateExpense={handleUpdateExpense}
        onDeleteExpense={handleDeleteExpense}
        inventory={inventory}
        onAddInventoryItem={handleAddInventoryItem}
        onUpdateInventoryItem={handleUpdateInventoryItem}
        onDeleteInventoryItem={handleDeleteInventoryItem}
        onSaveAllSettings={handleSaveAllSettings}
        onClearAllData={handleClearAllData}
        onSuccessfulLogout={handleLogoutSuccess}
        // Pass all settings as props
        companyName={companyName}
        logoUrl={logoUrl}
        aboutUsImageUrl={aboutUsImageUrl}
        whatsAppNumber={whatsAppNumber}
        address={address}
        phone={phone}
        email={email}
        socialLinks={socialLinks}
        showroomTitle={showroomTitle}
        showroomDescription={showroomDescription}
        heroTattooGunImageUrl={heroTattooGunImageUrl}
        bankName={bankName}
        accountNumber={accountNumber}
        branchCode={branchCode}
        accountType={accountType}
        vatNumber={vatNumber}
        isMaintenanceMode={isMaintenanceMode}
        apkUrl={apkUrl}
      />
    );
  }

  if (isIntroVisible) {
    return <WelcomeIntro isVisible={isIntroVisible} onEnter={handleEnter} logoUrl={logoUrl} />;
  }

  const showMaintenance = isMaintenanceMode && !user;

  return (
    <div className="relative">
      <div className={showMaintenance ? 'blur-sm brightness-50 pointer-events-none' : ''}>
        <Header onNavigate={navigate} logoUrl={logoUrl} companyName={companyName} />
        <main>
          <Hero portfolioData={portfolioData} onNavigate={navigate} heroTattooGunImageUrl={heroTattooGunImageUrl} />
          <SpecialsCollage specials={specialsData} whatsAppNumber={whatsAppNumber} />
          <AboutUs aboutUsImageUrl={aboutUsImageUrl} />
          <Showroom 
            showroomData={showroomData} 
            showroomTitle={showroomTitle} 
            showroomDescription={showroomDescription} 
          />
          <ContactForm onAddBooking={handleAddBooking} />
        </main>
        <Footer
          companyName={companyName}
          address={address}
          phone={phone}
          email={email}
          socialLinks={socialLinks}
          apkUrl={apkUrl}
        />
      </div>

      {showMaintenance && <MaintenancePage onNavigate={navigate} logoUrl={logoUrl} />}
    </div>
  );
};

export default App;

importScripts('https://storage.googleapis.com/workbox-cdn/releases/5.1.2/workbox-sw.js');

if (workbox) {
  console.log(`Yay! Workbox is loaded 🎉`);

  const { precacheAndRoute } = workbox.precaching;
  const { registerRoute, setCatchHandler } = workbox.routing;
  const { NetworkFirst, StaleWhileRevalidate, CacheFirst } = workbox.strategies;
  const { ExpirationPlugin } = workbox.expiration;
  const { CacheableResponsePlugin } = workbox.cacheableResponse;

  // Precache the essential app shell files for an instant offline experience.
  precacheAndRoute([
    { url: '/index.html', revision: null },
    { url: '/offline.html', revision: null },
    { url: '/manifest.json', revision: null },
  ]);

  // Use a NetworkFirst strategy for navigation requests.
  // This ensures users always get the latest content if they are online.
  registerRoute(
    ({ request }) => request.mode === 'navigate',
    new NetworkFirst({
      cacheName: 'pages',
      plugins: [
        new CacheableResponsePlugin({
          statuses: [200],
        }),
      ],
    })
  );

  // Set a global catch handler to provide the offline fallback page for failed navigations.
  setCatchHandler(({ event }) => {
    if (event.request.destination === 'document') {
      return caches.match('/offline.html');
    }
    return Response.error();
  });

  // Cache JavaScript and CSS files with a Stale-While-Revalidate strategy.
  // This provides assets quickly from the cache while updating them in the background.
  registerRoute(
    ({ request }) =>
      request.destination === 'script' || request.destination === 'style',
    new StaleWhileRevalidate({
      cacheName: 'static-resources',
    })
  );

  // Cache images with a CacheFirst strategy and an expiration policy.
  // This is ideal for images that don't change often.
  registerRoute(
    ({ request }) => request.destination === 'image',
    new CacheFirst({
      cacheName: 'images',
      plugins: [
        new ExpirationPlugin({
          maxEntries: 100, // Max number of images to cache
          maxAgeSeconds: 30 * 24 * 60 * 60, // 30 Days
          purgeOnQuotaError: true, // Automatically clean up if storage is full
        }),
        new CacheableResponsePlugin({
          statuses: [0, 200], // Cache opaque responses (for CORS images)
        }),
      ],
    })
  );

  // Cache Google Fonts stylesheets with Stale-While-Revalidate.
  registerRoute(
    ({url}) => url.origin === 'https://fonts.googleapis.com',
    new StaleWhileRevalidate({
      cacheName: 'google-fonts-stylesheets',
    })
  );

  // Cache Google Fonts webfont files with CacheFirst for a year.
  registerRoute(
    ({url}) => url.origin === 'https://fonts.gstatic.com',
    new CacheFirst({
      cacheName: 'google-fonts-webfonts',
      plugins: [
        new CacheableResponsePlugin({
          statuses: [0, 200],
        }),
        new ExpirationPlugin({
          maxAgeSeconds: 60 * 60 * 24 * 365, // 1 Year
          maxEntries: 30,
        }),
      ],
    })
  );

  // This message listener allows the new service worker to take control immediately.
  self.addEventListener('message', (event) => {
    if (event.data && event.data.type === 'SKIP_WAITING') {
      self.skipWaiting();
    }
  });

  // --- PWA Feature Listeners ---

  // Background Sync: Listens for the 'sync' event.
  self.addEventListener('sync', (event) => {
    if (event.tag === 'sync-booking-request') {
      console.log('Service Worker: Background sync event for booking request received.');
      event.waitUntil(
        new Promise((resolve, reject) => {
            console.log("Background Sync: Pretending to sync data...");
            setTimeout(resolve, 2000);
        })
      );
    }
  });

  // Periodic Sync: Listens for the 'periodicsync' event.
  self.addEventListener('periodicsync', (event) => {
    if (event.tag === 'get-latest-specials') {
      console.log('Service Worker: Periodic sync event for specials received.');
      event.waitUntil(
        new Promise((resolve, reject) => {
            console.log("Periodic Sync: Pretending to fetch latest specials...");
            setTimeout(resolve, 2000);
        })
      );
    }
  });

  // Push Notifications: Handles incoming push messages.
  self.addEventListener('push', (event) => {
    const data = event.data ? event.data.json() : { title: 'Bos Salon', body: 'You have a new message!' };
    const title = data.title;
    const options = {
      body: data.body,
      icon: 'https://i.ibb.co/gLSThX4v/unnamed-removebg-preview.png',
      badge: 'https://i.ibb.co/gLSThX4v/unnamed-removebg-preview.png'
    };
    event.waitUntil(self.registration.showNotification(title, options));
  });

  // Push Notifications: Handles clicks on notifications.
  self.addEventListener('notificationclick', (event) => {
    event.notification.close();
    event.waitUntil(
      clients.openWindow('/')
    );
  });

} else {
  console.log(`Boo! Workbox didn't load 😬`);
}

