      {/* Mobile Menu Overlay */}
      {isMenuOpen && (
        <div 
          className="md:hidden fixed inset-0 bg-brand-dark z-40 flex flex-col items-center justify-center text-center"
          role="dialog"
          aria-modal="true"
        >
