// --- MAIN APP COMPONENT ---
const App: React.FC = () => {
  // --- STATE ---
  const [user, setUser] = useState<User | null>(null);
  const [authChecked, setAuthChecked] = useState(false);
  const [loading, setLoading] = useState(true);
  const [dataError, setDataError] = useState<string | null>(null);

  const [portfolioData, setPortfolioData] = useState<PortfolioItem[]>([]);
  const [specialsData, setSpecialsData] = useState<SpecialItem[]>([]);
  const [showroomData, setShowroomData] = useState<Genre[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [inventory, setInventory] = useState<InventoryItem[]>([]);

  // Site settings state with updated defaults for Bos Salon
  const [companyName, setCompanyName] = useState('Bos Salon');
  const [logoUrl, setLogoUrl] = useState('https://i.ibb.co/gLSThX4v/unnamed-removebg-preview.png'); // Updated Logo
  const [aboutUsImageUrl, setAboutUsImageUrl] = useState('https://picsum.photos/seed/nail-artist/500/500');
  const [whatsAppNumber, setWhatsAppNumber] = useState('27795904162');
  const [address, setAddress] = useState('123 Nature Way, Green Valley, 45678');
  const [phone, setPhone] = useState('+27 12 345 6789');
  const [email, setEmail] = useState('bookings@bossalon.com');
  const [socialLinks, setSocialLinks] = useState<SocialLink[]>([]);
  const [showroomTitle, setShowroomTitle] = useState('Nail Art Gallery');
  const [showroomDescription, setShowroomDescription] = useState("Browse our collection of hand-painted designs and natural treatments.");
  const [heroTattooGunImageUrl, setHeroTattooGunImageUrl] = useState('https://cdn-icons-png.flaticon.com/512/3756/3756854.png'); // Default to a nail polish icon/image
  const [bankName, setBankName] = useState('FNB');
  const [accountNumber, setAccountNumber] = useState('1234567890');
  const [branchCode, setBranchCode] = useState('250655');
  const [accountType, setAccountType] = useState('Cheque');
  const [vatNumber, setVatNumber] = useState('');
  const [isMaintenanceMode, setIsMaintenanceMode] = useState(false);
  const [apkUrl, setApkUrl] = useState('');

  const [currentView, setCurrentView] = useState('home');
  const [isIntroVisible, setIsIntroVisible] = useState(true);

  // --- AUTH STATE LISTENER ---
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setAuthChecked(true);
    });
    return () => unsubscribe();
  }, []);

  // --- PUBLIC DATA FETCHING ---
  useEffect(() => {
    const unsubscribers: (() => void)[] = [];
    let isMounted = true;

    try {
      // Subscribe to settings document
      const settingsUnsub = onSnapshot(doc(db, "settings", "main"), (doc) => {
        if (doc.exists() && isMounted) {
          const settings = doc.data();
          setCompanyName(settings.companyName || 'Bos Salon');
          setLogoUrl(settings.logoUrl || 'https://i.ibb.co/gLSThX4v/unnamed-removebg-preview.png');
          setAboutUsImageUrl(settings.aboutUsImageUrl || 'https://picsum.photos/seed/nail-artist/500/500');
          setWhatsAppNumber(settings.whatsAppNumber || '27795904162');
          setAddress(settings.address || '123 Nature Way, Green Valley, 45678');
          setPhone(settings.phone || '+27 12 345 6789');
          setEmail(settings.email || 'bookings@bossalon.com');
          setSocialLinks(settings.socialLinks || []);
          setShowroomTitle(settings.showroomTitle || 'Nail Art Gallery');
          setShowroomDescription(settings.showroomDescription || "Browse our collection of hand-painted designs and natural treatments.");
          setHeroTattooGunImageUrl(settings.heroTattooGunImageUrl || 'https://cdn-icons-png.flaticon.com/512/3756/3756854.png');
          setBankName(settings.bankName || 'FNB');
          setAccountNumber(settings.accountNumber || '1234567890');
          setBranchCode(settings.branchCode || '250655');
          setAccountType(settings.accountType || 'Cheque');
          setVatNumber(settings.vatNumber || '');
          setIsMaintenanceMode(settings.isMaintenanceMode ?? false);
          setApkUrl(settings.apkUrl ?? '');
        }
      }, (error) => {
        console.error("Error listening to settings:", error);
        if(isMounted) setDataError("Failed to load critical site settings. This is likely a Firestore security rule issue. Please ensure the 'settings' collection is publicly readable.");
      });
      unsubscribers.push(settingsUnsub);

      // Subscribe to public collections
      const publicCollections: { name: string, setter: React.Dispatch<React.SetStateAction<any[]>> }[] = [
        { name: 'portfolio', setter: setPortfolioData },
        { name: 'specials', setter: setSpecialsData },
        { name: 'showroom', setter: setShowroomData },
      ];

      publicCollections.forEach(({ name, setter }) => {
        const unsub = onSnapshot(collection(db, name), (snapshot) => {
          if (isMounted) setter(snapshot.docs.map(d => ({ id: d.id, ...d.data() })));
        }, (error) => {
          console.error(`Error listening to public collection ${name}:`, error);
          if (isMounted) setDataError(`Failed to load data for '${name}'. This is likely due to a Firestore security rule misconfiguration. Please ensure the '${name}' collection is publicly readable.`);
        });
        unsubscribers.push(unsub);
      });

    } catch (error) {
      console.error("Error setting up public Firestore listeners:", error);
      if (isMounted) setDataError("A critical error occurred while trying to connect to the database.");
    }

    return () => {
      isMounted = false;
      unsubscribers.forEach(unsub => unsub());
    };
  }, []);

  // --- PRIVATE (ADMIN) DATA FETCHING ---
  useEffect(() => {
    if (!user) {
      setBookings([]);
      setExpenses([]);
      setInventory([]);
      return;
    }

    // User is authenticated, fetch private data.
    const unsubscribers: (() => void)[] = [];
    let isMounted = true;
    try {
      const privateCollections: { name: string, setter: React.Dispatch<React.SetStateAction<any[]>> }[] = [
        { name: 'bookings', setter: setBookings },
        { name: 'expenses', setter: setExpenses },
        { name: 'inventory', setter: setInventory },
      ];

      privateCollections.forEach(({ name, setter }) => {
        const unsub = onSnapshot(collection(db, name), (snapshot) => {
          if (isMounted) setter(snapshot.docs.map(d => ({ id: d.id, ...d.data() })));
        }, (error) => {
            console.error(`Error listening to private collection ${name}:`, error);
            if (isMounted) setDataError(`Failed to load private data for '${name}'. Your account may not have the correct permissions.`);
        });
        unsubscribers.push(unsub);
      });
    } catch (error) {
      console.error("Error setting up private Firestore listeners:", error);
      if (isMounted) setDataError("A critical error occurred while trying to load administrator data.");
    }

    return () => {
      isMounted = false;
      unsubscribers.forEach(unsub => unsub());
    };
  }, [user]); // This effect depends on the user's auth state.

  // --- LOADING STATE ---
  useEffect(() => {
    if (authChecked) {
      setLoading(false);
    }
  }, [authChecked]);


  // --- INTRO & NAVIGATION ---
  useEffect(() => {
    if (sessionStorage.getItem('introShown')) {
      setIsIntroVisible(false);
    }
  }, []);

  const handleEnter = () => {
    sessionStorage.setItem('introShown', 'true');
    setIsIntroVisible(false);
  };

  const navigate = (view: 'home' | 'admin') => setCurrentView(view);

  const handleLogoutSuccess = () => {
    setUser(null); // Explicitly clear the user state for an immediate UI update
    navigate('home');
  };

  // --- CRUD (Create, Read, Update, Delete) FUNCTIONS ---

  // Generic update DB doc
  const updateItem = async <T extends {id: string}>(collectionName: string, item: T) => {
    try {
      const { id, ...data } = item;
      await updateDoc(doc(db, collectionName, id), data);
    } catch (error) {
      console.error(`Error updating ${collectionName}:`, error);
      alert(`Failed to update item in ${collectionName}. Please check the console for details and verify your Firestore security rules.`);
    }
  };

  // Generic add DB doc
  const addItem = async <T extends {}>(collectionName: string, item: T) => {
    try {
      await addDoc(collection(db, collectionName), item);
    } catch (error) {
      console.error(`Error adding ${collectionName}:`, error);
      alert(`Failed to add item to ${collectionName}. Please check the console for details and verify your Firestore security rules.`);
    }
  };

  // Generic delete DB doc
  const deleteItem = async (collectionName: string, itemId: string) => {
    try {
      await deleteDoc(doc(db, collectionName, itemId));
    } catch (error) {
      console.error(`Error deleting ${collectionName}:`, error);
      alert(`Failed to delete item from ${collectionName}. Please check the console for details and verify your Firestore security rules.`);
    }
  };

  // Portfolio
  const handleUpdatePortfolioItem = async (item: PortfolioItem) => await updateItem('portfolio', item);
  const handleAddPortfolioItem = async (item: Omit<PortfolioItem, 'id'>) => await addItem('portfolio', item);
  const handleDeletePortfolioItem = async (itemId: string) => await deleteItem('portfolio', itemId);

  // Specials
  const handleUpdateSpecialItem = async (item: SpecialItem) => await updateItem('specials', item);
  const handleAddSpecialItem = async (item: Omit<SpecialItem, 'id'>) => await addItem('specials', item);
  const handleDeleteSpecialItem = async (itemId: string) => await deleteItem('specials', itemId);

  // Showroom
  const handleUpdateShowroomGenre = async (item: Genre) => await updateItem('showroom', item);
  const handleAddShowroomGenre = async (item: Omit<Genre, 'id'>) => await addItem('showroom', item);
