// --- MAIN APP COMPONENT ---
const App: React.FC = () => {
  // --- STATE ---
  const [user, setUser] = useState<any | null>(null);
  const [authChecked, setAuthChecked] = useState(false);
  const [loading, setLoading] = useState(true);
  const [dataError, setDataError] = useState<string | null>(null);

  const [portfolioData, setPortfolioData] = useState<PortfolioItem[]>([]);
  const [specialsData, setSpecialsData] = useState<SpecialItem[]>([]);
  const [showroomData, setShowroomData] = useState<Genre[]>([]);
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [inventory, setInventory] = useState<InventoryItem[]>([]);

  // Site settings state with updated defaults for Bos Salon
  const [companyName, setCompanyName] = useState('Die Bos Salon');
  const [logoUrl, setLogoUrl] = useState('https://i.ibb.co/gLSThX4v/unnamed-removebg-preview.png'); // Updated Logo
  const [aboutUsImageUrl, setAboutUsImageUrl] = useState('https://picsum.photos/seed/nail-artist/500/500');
  const [whatsAppNumber, setWhatsAppNumber] = useState('27795904162');
  const [address, setAddress] = useState('123 Nature Way, Green Valley, 45678');
  const [phone, setPhone] = useState('+27 12 345 6789');
  const [email, setEmail] = useState('bookings@bossalon.com');
  const [socialLinks, setSocialLinks] = useState<SocialLink[]>([]);
  const [showroomTitle, setShowroomTitle] = useState('Nail Art Gallery');
  const [showroomDescription, setShowroomDescription] = useState("Browse our collection of hand-painted designs and natural treatments.");
  const [heroTattooGunImageUrl, setHeroTattooGunImageUrl] = useState('https://cdn-icons-png.flaticon.com/512/3756/3756854.png'); 
  const [bankName, setBankName] = useState('FNB');
  const [accountNumber, setAccountNumber] = useState('1234567890');
  const [branchCode, setBranchCode] = useState('250655');
  const [accountType, setAccountType] = useState('Cheque');
  const [vatNumber, setVatNumber] = useState('');
  const [isMaintenanceMode, setIsMaintenanceMode] = useState(false);
  const [apkUrl, setApkUrl] = useState('');

  const [currentView, setCurrentView] = useState('home');
  const [isIntroVisible, setIsIntroVisible] = useState(true);

  // --- AUTH STATE LISTENER ---
  useEffect(() => {
    const unsubscribe = dbOnAuthStateChange((currentUser) => {
      setUser(currentUser);
      setAuthChecked(true);
    });
    return () => unsubscribe();
  }, []);

  // --- PUBLIC DATA FETCHING ---
  useEffect(() => {
    const unsubscribers: (() => void)[] = [];

    try {
      // Subscribe to settings document
      const unsubSettings = dbSubscribeToDoc("settings", "main", (settings: any) => {
          if (settings) {
            setCompanyName(settings.companyName || 'Die Bos Salon');
            setLogoUrl(settings.logoUrl || 'https://i.ibb.co/gLSThX4v/unnamed-removebg-preview.png');
            setAboutUsImageUrl(settings.aboutUsImageUrl || 'https://picsum.photos/seed/nail-artist/500/500');
            setWhatsAppNumber(settings.whatsAppNumber || '27795904162');
            setAddress(settings.address || '123 Nature Way, Green Valley, 45678');
            setPhone(settings.phone || '+27 12 345 6789');
            setEmail(settings.email || 'bookings@bossalon.com');
            setSocialLinks(settings.socialLinks || []);
            setShowroomTitle(settings.showroomTitle || 'Nail Art Gallery');
            setShowroomDescription(settings.showroomDescription || "Browse our collection of hand-painted designs and natural treatments.");
            setHeroTattooGunImageUrl(settings.heroTattooGunImageUrl || 'https://cdn-icons-png.flaticon.com/512/3756/3756854.png');
            setBankName(settings.bankName || 'FNB');
            setAccountNumber(settings.accountNumber || '1234567890');
            setBranchCode(settings.branchCode || '250655');
            setAccountType(settings.accountType || 'Cheque');
            setVatNumber(settings.vatNumber || '');
            setIsMaintenanceMode(settings.isMaintenanceMode ?? false);
            setApkUrl(settings.apkUrl ?? '');
          }
      });
      unsubscribers.push(unsubSettings);

      // Subscribe to public collections
      unsubscribers.push(dbSubscribeToCollection('portfolio', (data) => setPortfolioData(data)));
      unsubscribers.push(dbSubscribeToCollection('specials', (data) => setSpecialsData(data)));
      unsubscribers.push(dbSubscribeToCollection('showroom', (data) => setShowroomData(data)));

    } catch (error) {
      console.error("Error setting up DB listeners:", error);
      setDataError("A critical error occurred while trying to connect to the database.");
    }

    return () => {
      unsubscribers.forEach(unsub => unsub());
    };
  }, []);

  // --- PRIVATE (ADMIN) DATA FETCHING ---
  useEffect(() => {
    if (!user) {
      setBookings([]);
      setExpenses([]);
      setInventory([]);
      return;
    }

    const unsubscribers: (() => void)[] = [];
    try {
        unsubscribers.push(dbSubscribeToCollection('bookings', (data) => setBookings(data)));
        unsubscribers.push(dbSubscribeToCollection('expenses', (data) => setExpenses(data)));
        unsubscribers.push(dbSubscribeToCollection('inventory', (data) => setInventory(data)));
    } catch (error) {
      console.error("Error setting up private listeners:", error);
      setDataError("A critical error occurred while trying to load administrator data.");
    }

    return () => {
      unsubscribers.forEach(unsub => unsub());
    };
  }, [user]); 

  // --- LOADING STATE ---
  useEffect(() => {
    if (authChecked) {
      setLoading(false);
    }
  }, [authChecked]);


  // --- INTRO & NAVIGATION ---
  useEffect(() => {
    if (sessionStorage.getItem('introShown')) {
      setIsIntroVisible(false);
    }
  }, []);

  const handleEnter = () => {
    sessionStorage.setItem('introShown', 'true');
    setIsIntroVisible(false);
  };

  const navigate = (view: 'home' | 'admin') => setCurrentView(view);

  const handleLogoutSuccess = async () => {
    await dbLogout();
    setUser(null); 
    navigate('home');
  };

  // --- CRUD FUNCTIONS (Adapter Wrappers) ---
  const handleUpdatePortfolioItem = async (item: PortfolioItem) => await dbUpdateItem('portfolio', item);
  const handleAddPortfolioItem = async (item: Omit<PortfolioItem, 'id'>) => await dbAddItem('portfolio', item);
  const handleDeletePortfolioItem = async (itemId: string) => await dbDeleteItem('portfolio', itemId);

  const handleUpdateSpecialItem = async (item: SpecialItem) => await dbUpdateItem('specials', item);
  const handleAddSpecialItem = async (item: Omit<SpecialItem, 'id'>) => await dbAddItem('specials', item);
  const handleDeleteSpecialItem = async (itemId: string) => await dbDeleteItem('specials', itemId);

  const handleUpdateShowroomGenre = async (item: Genre) => await dbUpdateItem('showroom', item);
  const handleAddShowroomGenre = async (item: Omit<Genre, 'id'>) => await dbAddItem('showroom', item);
  const handleDeleteShowroomGenre = async (itemId: string) => await dbDeleteItem('showroom', itemId);

  const handleAddBooking = async (newBookingData: Omit<Booking, 'id' | 'status' | 'bookingType'>) => {
    const newBooking = {
      ...newBookingData,
      status: 'pending',
      bookingType: 'online',
    };
    await dbAddItem('bookings', newBooking);
  };
  const handleManualAddBooking = async (newBookingData: Omit<Booking, 'id' | 'bookingType'>) => {
    const newBooking = {
      ...newBookingData,
      bookingType: 'manual',
    };
    await dbAddItem('bookings', newBooking);
  };
  const handleUpdateBooking = async (item: Booking) => await dbUpdateItem('bookings', item);

  const handleAddExpense = async (newExpense: Omit<Expense, 'id'>) => await dbAddItem('expenses', newExpense);
  const handleUpdateExpense = async (updatedExpense: Expense) => await dbUpdateItem('expenses', updatedExpense);
  const handleDeleteExpense = async (expenseId: string) => await dbDeleteItem('expenses', expenseId);

  const handleAddInventoryItem = async (newItem: Omit<InventoryItem, 'id'>) => await dbAddItem('inventory', newItem);
  const handleUpdateInventoryItem = async (updatedItem: InventoryItem) => await dbUpdateItem('inventory', updatedItem);
  const handleDeleteInventoryItem = async (itemId: string) => await dbDeleteItem('inventory', itemId);

  const handleSaveAllSettings = async (settings: any) => {
    await dbSetDoc('settings', 'main', settings);
  };

  const handleClearAllData = async () => {
      if (!window.confirm("ARE YOU SURE? This will delete ALL content from your live database. This is irreversible.")) return;
      const collections = ['portfolio', 'specials', 'showroom', 'bookings', 'expenses', 'inventory'];
      try {
          for (const col of collections) {
              await dbClearCollection(col as any);
          }
          alert('All live data has been cleared.');
      } catch (error) {
          console.error("Error clearing data:", error);
          alert("An error occurred while clearing data. Check console for details.");
      }
  };

  // --- RENDER LOGIC ---

  if (loading) {
    return (
