  const delay = -Math.random() * 20; // Start at random times
  const rotation = Math.random() * 360;
  const zIndex = Math.floor(Math.random() * 10);
  const blur = Math.random() * 1; // Slight blur for depth

  return {
    id: i,
    Icon,
    style: {
      left: `${left}%`,
      top: `${top}%`,
      width: `${size}px`,
      height: `${size}px`,
      animationDuration: `${duration}s`,
      animationDelay: `${delay}s`,
      transform: `rotate(${rotation}deg)`,
      zIndex: zIndex,
      // Increased visibility of outline: drop-shadow with slight opacity
      filter: `blur(${blur * 0.5}px) drop-shadow(0 0 1px rgba(0,0,0,0.6))`, 
