    bookingToEdit?: Booking | null;
}> = ({ isOpen, onClose, onSave, bookingToEdit }) => {

    const getInitialFormData = (): Booking => {
        if (bookingToEdit) {
            return { ...bookingToEdit };
        }
        return {
            id: '', // Will be set on save
            name: '',
            email: '',
            message: '',
            bookingDate: new Date().toISOString().split('T')[0],
            status: 'pending',
            bookingType: 'manual',
            totalCost: undefined,
            amountPaid: undefined,
