                                    <option value="card">Card</option>
                                    <option value="eft">EFT / Transfer</option>
                                    <option value="other">Other</option>
                                </select>
                           </div>
                        </div>
                    </div>
                    <div className="flex justify-end gap-4 pt-6 border-t border-admin-dark-border">
