                                        <span>✏️</span>
                                    </button>
                                </div>
                            </div>
                        </div>
                    );
                })
            ) : (
                <p className="text-center py-8 text-admin-dark-text-secondary md:col-span-2 xl:col-span-3">No bookings found for this filter.</p>
            )}
            </div>
        </div>
    );
};


const BookingCalendarWidget: React.FC<{ bookings: Booking[], selectedDate: string | null, onDateSelect: (date: string | null) => void }> = ({ bookings, selectedDate, onDateSelect }) => {
    const today = new Date();
    const [currentDate, setCurrentDate] = useState(today);

    const bookingsByDate = bookings.reduce((acc, booking) => {
        const date = new Date(booking.bookingDate).toDateString();
        if (!acc[date]) acc[date] = [];
        acc[date].push(booking);
        return acc;
    }, {} as Record<string, Booking[]>);

    const changeMonth = (delta: number) => {
        setCurrentDate(prev => {
            const newDate = new Date(prev);
            newDate.setMonth(prev.getMonth() + delta);
            return newDate;
        });
    };

    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const firstDayOfMonth = new Date(year, month, 1).getDay();
    const blanks = Array(firstDayOfMonth).fill(null);
    const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);

    const upcomingConfirmed = bookings
        .filter(b => b.status === 'confirmed' && new Date(b.bookingDate) >= new Date(today.toDateString()))
        .sort((a, b) => new Date(a.bookingDate).getTime() - new Date(b.bookingDate).getTime())
        .slice(0, 5);

    const daysUntil = (dateStr: string) => {
        const diffTime = new Date(dateStr).getTime() - new Date(today.toDateString()).getTime();
        return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    };

    return (
        <div className="bg-admin-dark-card border border-admin-dark-border rounded-xl shadow-lg p-4 space-y-6">
            <div data-tour-id="dashboard-calendar">
                <h3 className="font-bold text-lg text-admin-dark-text mb-4">Booking Calendar</h3>
                <div className="flex justify-between items-center mb-2">
                    <button onClick={() => changeMonth(-1)} className="text-admin-dark-text-secondary hover:text-admin-dark-text">◀</button>
                    <span className="font-semibold text-admin-dark-text text-sm">{currentDate.toLocaleString('default', { month: 'long', year: 'numeric' })}</span>
                    <button onClick={() => changeMonth(1)} className="text-admin-dark-text-secondary hover:text-admin-dark-text">▶</button>
                </div>
                <div className="grid grid-cols-7 gap-1 text-center text-xs text-admin-dark-text-secondary">
                    {['S', 'M', 'T', 'W', 'T', 'F', 'S'].map(d => <div key={d} className="h-6 flex items-center justify-center font-semibold">{d}</div>)}
                    {blanks.map((_, i) => <div key={`b-${i}`}></div>)}
                    {days.map(day => {
                        const dateObj = new Date(year, month, day);
                        const date = dateObj.toDateString();
                        const hasBooking = bookingsByDate[date];
                        const isSelected = selectedDate ? new Date(selectedDate).toDateString() === date : false;
                        const isToday = date === today.toDateString();
                        return (
                            <div key={day} onClick={() => onDateSelect(isSelected ? null : dateObj.toISOString())} className={`h-8 rounded-full flex items-center justify-center text-xs transition-colors cursor-pointer ${isSelected ? 'bg-admin-dark-primary text-white ring-2 ring-white shadow-lg' : isToday ? 'ring-1 ring-admin-dark-primary text-admin-dark-primary' : hasBooking ? 'bg-admin-dark-primary/30 text-admin-dark-text font-bold hover:bg-admin-dark-primary/60' : 'hover:bg-black/5'}`}>
                                {day}
                            </div>
                        )
                    })}
                </div>
            </div>
            <div data-tour-id="dashboard-reminder-clock">
                 <h3 className="font-bold text-lg text-admin-dark-text mb-4">Reminder Clock</h3>
                 <div className="space-y-3">
                    {upcomingConfirmed.length > 0 ? upcomingConfirmed.map(booking => {
                        const daysLeft = daysUntil(booking.bookingDate);
                        return (
                            <div key={booking.id} className="bg-admin-dark-bg/50 p-3 rounded-lg">
                                <div className="flex justify-between items-center">
                                    <p className="text-sm font-semibold text-admin-dark-text">{booking.name}</p>
                                    <p className="text-xs font-bold text-green-600">
                                        {daysLeft === 0 ? "Today" : daysLeft === 1 ? "Tomorrow" : `${daysLeft} days`}
                                    </p>
                                </div>
                                <p className="text-xs text-admin-dark-text-secondary mt-1">{new Date(booking.bookingDate).toLocaleDateString('en-ZA', {weekday: 'long', day: 'numeric', month: 'short'})}</p>
                            </div>
                        );
                    }) : <p className="text-sm text-admin-dark-text-secondary text-center py-8">No upcoming confirmed bookings.</p>}
                 </div>
            </div>
        </div>
    );
};


type AdminTab = 'dashboard' | 'clients' | 'specials' | 'art' | 'financials' | 'settings';
type ArtSubTab = 'portfolio' | 'showroom';
type TourKey = 'dashboard' | 'art' | 'financials' | 'settings';

interface AdminDashboardComponentProps extends AdminPageProps {
  onLogout: () => void;
}

const AdminDashboard: React.FC<AdminDashboardComponentProps> = (props) => {
  const [activeTab, setActiveTab] = useState<AdminTab>('dashboard');
  const [artSubTab, setArtSubTab] = useState<ArtSubTab>('portfolio');
  const [previousTab, setPreviousTab] = useState<AdminTab>('dashboard');
  const [selectedDate, setSelectedDate] = useState<string | null>(null);
  const [isBookingModalOpen, setIsBookingModalOpen] = useState(false);
  const [bookingToEdit, setBookingToEdit] = useState<Booking | null>(null);
  const [activeTour, setActiveTour] = useState<TourKey | null>(null);

  const handleTabChange = (tab: AdminTab) => {
    setPreviousTab(activeTab);
    setActiveTab(tab);
  };

  const handleBack = () => {
    setActiveTab(previousTab);
  };

  const handleOpenCreateModal = () => {
    setBookingToEdit(null);
    setIsBookingModalOpen(true);
  };

  const handleOpenEditModal = (booking: Booking) => {
    setBookingToEdit(booking);
    setIsBookingModalOpen(true);
  };

  const handleSaveBooking = async (bookingData: Booking) => {
    if (bookingToEdit) { // Update existing booking
        await props.onUpdateBooking(bookingData);
    } else { // Create new manual booking
        const { id, bookingType, ...newBookingData } = bookingData;
        await props.onManualAddBooking(newBookingData);
    }
  };

  const renderDashboard = () => (
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 items-start">
        <div className="lg:col-span-2">
            <BookingsManager 
                bookings={props.bookings} 
                onUpdateBooking={props.onUpdateBooking} 
                selectedDate={selectedDate} 
                onClearDateFilter={() => setSelectedDate(null)}
                onAddManualBooking={handleOpenCreateModal}
                onEditBooking={handleOpenEditModal}
                startTour={setActiveTour}
            />
        </div>
        <div className="space-y-6">
            <BookingCalendarWidget bookings={props.bookings} selectedDate={selectedDate} onDateSelect={setSelectedDate} />
        </div>
      </div>
  );

  const renderArtManagement = () => (
    <div className="space-y-6">
        <div data-tour-id="art-subtabs" className="flex items-center gap-2 bg-admin-dark-bg p-1 rounded-lg self-start max-w-sm">
            <button onClick={() => setArtSubTab('portfolio')} className={`w-full px-4 py-1.5 text-sm font-bold rounded-lg transition-colors capitalize ${artSubTab === 'portfolio' ? 'bg-admin-dark-primary text-white' : 'text-admin-dark-text-secondary hover:bg-black/5'}`}>Portfolio</button>
            <button data-tour-id="art-showroom-tab" onClick={() => setArtSubTab('showroom')} className={`w-full px-4 py-1.5 text-sm font-bold rounded-lg transition-colors capitalize ${artSubTab === 'showroom' ? 'bg-admin-dark-primary text-white' : 'text-admin-dark-text-secondary hover:bg-black/5'}`}>Showroom</button>
        </div>
        {artSubTab === 'portfolio' ? (
            <PortfolioManager 
              portfolioData={props.portfolioData} 
              onAddPortfolioItem={props.onAddPortfolioItem}
              onUpdatePortfolioItem={props.onUpdatePortfolioItem}
              onDeletePortfolioItem={props.onDeletePortfolioItem}
              startTour={setActiveTour} 
            />
        ) : (
            <ShowroomManager 
              showroomData={props.showroomData} 
              onAddShowroomGenre={props.onAddShowroomGenre}
              onUpdateShowroomGenre={props.onUpdateShowroomGenre}
              onDeleteShowroomGenre={props.onDeleteShowroomGenre}
              startTour={setActiveTour} 
            />
        )}
    </div>
  );

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return renderDashboard();
      case 'clients':
        return <ClientsManager bookings={props.bookings} />;
      case 'specials':
        return <SpecialsManager specialsData={props.specialsData} onAddSpecialItem={props.onAddSpecialItem} onUpdateSpecialItem={props.onUpdateSpecialItem} onDeleteSpecialItem={props.onDeleteSpecialItem} />;
      case 'art':
        return renderArtManagement();
      case 'financials':
        return <FinancialsManager {...props} startTour={setActiveTour} />;
      case 'settings':
        return <SettingsManager {...props} startTour={setActiveTour} />;
      default:
        return renderDashboard();
    }
  };

  const navItems: { id: AdminTab, label: string, icon: React.ReactNode }[] = [
      { id: 'dashboard', label: 'Dashboard', icon: <IconDashboard /> },
      { id: 'clients', label: 'Clients', icon: <IconClients /> },
      { id: 'specials', label: 'Specials', icon: <IconSpecials /> },
      { id: 'financials', label: 'Financials', icon: <IconFinancials /> },
      { id: 'art', label: 'Art', icon: <IconArt /> },
      { id: 'settings', label: 'Settings', icon: <IconSettings /> },
  ];

  return (
    <div className="h-screen font-sans bg-admin-dark-bg text-admin-dark-text flex flex-col overflow-hidden" role="application">

      <BookingModal 
        isOpen={isBookingModalOpen}
        onClose={() => setIsBookingModalOpen(false)}
        onSave={handleSaveBooking}
        bookingToEdit={bookingToEdit}
      />

      <TrainingGuide activeTour={activeTour} onClose={() => setActiveTour(null)} />

      <header className="p-4 md:p-6 flex items-center justify-between flex-wrap gap-4 border-b border-admin-dark-border flex-shrink-0 bg-admin-dark-card/90">
          <div className="flex items-center gap-4">
               {activeTab !== 'dashboard' && (
                  <button onClick={handleBack} className="p-2 bg-admin-dark-card/80 rounded-full hover:bg-black/10 transition-colors">
                      <IconBack />
                  </button>
              )}
              <img src={props.logoUrl} alt="Logo" className="w-12 h-12 object-contain rounded-full border-2 border-admin-dark-primary p-1" />
              <div>
                  <p className="text-admin-dark-text-secondary text-sm">Welcome back!</p>
                  <h1 className="font-bold text-xl text-admin-dark-text capitalize">
                      {activeTab === 'dashboard' ? 'Dashboard Overview' : `${activeTab} Management`}
                  </h1>
              </div>
          </div>
           <div className="flex items-center gap-2 sm:gap-4 flex-wrap">
              <button onClick={() => props.onNavigate('home')} className="text-sm text-center py-2 px-4 text-admin-dark-text-secondary hover:text-admin-dark-text transition-colors">View Site</button>
              <button onClick={props.onLogout} className="bg-admin-dark-card border border-admin-dark-border px-4 py-2 rounded-lg font-bold text-sm text-red-400 hover:bg-red-500/10 transition-colors">Logout</button>
          </div>
      </header>

      <div data-tour-id="main-navigation" className="flex-shrink-0 bg-admin-dark-card/80 backdrop-blur-lg border-b border-admin-dark-border h-16">
          <nav className="container mx-auto grid grid-cols-6 h-full">
              {navItems.map(item => (
                  <button 
                      key={item.id} 
                      onClick={() => handleTabChange(item.id)}
                      className={`flex flex-col items-center justify-center gap-1 w-full h-full transition-colors duration-200 ${activeTab === item.id ? 'text-admin-dark-primary bg-admin-dark-primary/10' : 'text-admin-dark-text-secondary hover:text-admin-dark-text'}`}
                      aria-current={activeTab === item.id}
                  >
                      {item.icon}
                      <span className="text-[10px] font-bold capitalize">{item.label}</span>
                  </button>
              ))}
          </nav>
      </div>

      <main className="flex-1 p-4 md:p-6 overflow-y-auto" id="admin-main-content">
        {renderContent()}
      </main>

    </div>
  );
};

