        <button type="button" onClick={onCancel} className="px-4 py-2 text-admin-dark-text-secondary hover:text-white transition-colors">Cancel</button>
        <button type="submit" disabled={loading} className="bg-admin-dark-primary text-white px-6 py-2 rounded-lg font-bold hover:bg-opacity-90 transition-opacity disabled:opacity-50">
          {loading ? 'Saving...' : 'Save Special'}
        </button>
      </div>
    </form>
  );
};

interface SpecialsManagerProps {
  specialsData: SpecialItem[];
  onAddSpecialItem: (item: Omit<SpecialItem, 'id'>) => Promise<void>;
  onUpdateSpecialItem: (item: SpecialItem) => Promise<void>;
  onDeleteSpecialItem: (id: string) => Promise<void>;
}

const SpecialsManager: React.FC<SpecialsManagerProps> = ({ specialsData, onAddSpecialItem, onUpdateSpecialItem, onDeleteSpecialItem }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [editingItem, setEditingItem] = useState<SpecialItem | null>(null);

  const handleSave = async (data: any) => {
    try {
      let imageUrl = data.imageUrl || '';
      if (data.imageFile) {
        imageUrl = await dbUploadFile(data.imageFile, 'specials');
      }

      const itemPayload = {
        title: data.title,
        description: data.description,
        price: data.price,
        active: data.active !== false, // Default to true if undefined
        imageUrl,
      };

      if (editingItem) {
        await onUpdateSpecialItem({ ...itemPayload, id: editingItem.id } as SpecialItem);
      } else {
        await onAddSpecialItem(itemPayload as any);
      }
      setIsAdding(false);
      setEditingItem(null);
    } catch (error) {
      console.error("Error saving special:", error);
      alert("Failed to save special.");
    }
  };

  const handleDelete = async (id: string) => {
    if(window.confirm("Are you sure you want to remove this special offer?")) {
      await onDeleteSpecialItem(id);
    }
  };

  return (
    <div className="bg-admin-dark-card border border-admin-dark-border rounded-xl shadow-lg p-6">
      <header className="flex justify-between items-center mb-8">
        <div>
          <h2 className="text-xl font-bold text-white">Public Specials</h2>
          <p className="text-sm text-admin-dark-text-secondary">Manage offers displayed on the "Seasonal Specials" section of your website.</p>
        </div>
        {!isAdding && !editingItem && (
          <button onClick={() => setIsAdding(true)} className="flex items-center gap-2 bg-admin-dark-primary text-white px-4 py-2 rounded-lg font-bold text-sm hover:opacity-90">
            <PlusIcon className="w-5 h-5" /> Add Special
          </button>
        )}
      </header>

      {(isAdding || editingItem) && (
        <SpecialForm 
          initialItem={editingItem || {}} 
          onSave={handleSave} 
          onCancel={() => { setIsAdding(false); setEditingItem(null); }} 
        />
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {specialsData.map(special => (
          <div key={special.id} className={`bg-admin-dark-bg/50 border ${special.active ? 'border-green-500/30' : 'border-red-500/30'} rounded-lg overflow-hidden flex flex-col`}>
            <div className="relative h-48">
              <img src={special.imageUrl} alt={special.title} className="w-full h-full object-cover" />
              <div className="absolute top-2 right-2 flex gap-2">
                <span className={`px-2 py-1 text-xs font-bold rounded text-white ${special.active ? 'bg-green-600' : 'bg-red-500'}`}>
                  {special.active ? 'Active' : 'Inactive'}
                </span>
              </div>
              <div className="absolute bottom-2 right-2 bg-black/70 text-white px-3 py-1 rounded-full text-sm font-bold">
                R{special.price}
              </div>
            </div>
            <div className="p-4 flex-grow">
              <h4 className="font-bold text-white text-lg mb-1">{special.title}</h4>
              <p className="text-sm text-admin-dark-text-secondary">{special.description}</p>
            </div>
            <div className="p-4 border-t border-admin-dark-border flex justify-end gap-2 bg-black/20">
              <button onClick={() => setEditingItem(special)} className="p-2 text-admin-dark-text-secondary hover:text-white hover:bg-white/10 rounded-full transition-colors">
                <PencilIcon className="w-5 h-5" />
              </button>
              <button onClick={() => handleDelete(special.id)} className="p-2 text-red-400 hover:text-red-300 hover:bg-red-900/20 rounded-full transition-colors">
                <TrashIcon className="w-5 h-5" />
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

