import React, { useState, useMemo } from 'react';
import { Booking } from '../../App';

interface ClientProfile {
  name: string;
  email: string;
  phone?: string; // from whatsappNumber
  totalSpend: number;
  visitCount: number;
  lastVisit: string;
  bookings: Booking[];
  preferredPayment: string;
}

const ClientsManager: React.FC<{ bookings: Booking[] }> = ({ bookings }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedClient, setSelectedClient] = useState<ClientProfile | null>(null);

  const clients = useMemo(() => {
    const clientMap: Record<string, ClientProfile> = {};

    bookings.forEach(booking => {
      // Normalize email as ID
      const email = booking.email.toLowerCase().trim();
      if (!email) return;

      if (!clientMap[email]) {
        clientMap[email] = {
          name: booking.name,
          email: email,
          phone: booking.whatsappNumber,
          totalSpend: 0,
          visitCount: 0,
          lastVisit: booking.bookingDate,
          bookings: [],
          preferredPayment: 'Unknown'
        };
      }

      const client = clientMap[email];

      // Update basic info if newer exists
      if (!client.phone && booking.whatsappNumber) client.phone = booking.whatsappNumber;

      // Add booking
      client.bookings.push(booking);

      // Calc stats
      if (booking.status === 'completed') {
        client.totalSpend += (booking.totalCost || 0); // Use totalCost if tracked, or assume full price
        client.visitCount += 1;
      }

      // Track latest visit
      if (new Date(booking.bookingDate) > new Date(client.lastVisit)) {
        client.lastVisit = booking.bookingDate;
      }
    });

    // Determine preferred payment method
    Object.values(clientMap).forEach(client => {
      const methods: Record<string, number> = {};
      client.bookings.forEach(b => {
        if (b.paymentMethod) {
          methods[b.paymentMethod] = (methods[b.paymentMethod] || 0) + 1;
        }
      });
      const sortedMethods = Object.entries(methods).sort((a,b) => b[1] - a[1]);
      if (sortedMethods.length > 0) {
        client.preferredPayment = sortedMethods[0][0];
      }
    });

    return Object.values(clientMap).sort((a, b) => b.totalSpend - a.totalSpend); // Sort by VIP status (spend)
  }, [bookings]);

  const filteredClients = clients.filter(c => 
    c.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    c.email.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 h-[calc(100vh-140px)]">
      {/* Client List */}
      <div className="bg-admin-dark-card border border-admin-dark-border rounded-xl shadow-lg p-6 flex flex-col h-full">
        <h2 className="text-xl font-bold text-white mb-4">Client Database</h2>
        <input 
          type="text" 
          placeholder="Search clients..." 
          value={searchTerm}
          onChange={e => setSearchTerm(e.target.value)}
          className="w-full bg-admin-dark-bg border border-admin-dark-border rounded-lg p-2.5 text-admin-dark-text mb-4 focus:ring-2 focus:ring-admin-dark-primary outline-none"
        />
        <div className="flex-grow overflow-y-auto space-y-2 pr-2">
          {filteredClients.map(client => (
            <div 
              key={client.email}
              onClick={() => setSelectedClient(client)}
              className={`p-3 rounded-lg cursor-pointer transition-colors border ${selectedClient?.email === client.email ? 'bg-admin-dark-primary/20 border-admin-dark-primary' : 'bg-admin-dark-bg/30 border-transparent hover:bg-admin-dark-bg/50'}`}
            >
              <div className="flex justify-between items-start">
                <h4 className="font-bold text-white">{client.name}</h4>
                <span className="text-xs text-green-400 font-mono">R{client.totalSpend.toFixed(0)}</span>
              </div>
              <p className="text-xs text-admin-dark-text-secondary">{client.email}</p>
            </div>
          ))}
        </div>
      </div>

      {/* Client Detail View */}
      <div className="lg:col-span-2 bg-admin-dark-card border border-admin-dark-border rounded-xl shadow-lg p-6 h-full overflow-y-auto">
        {selectedClient ? (
          <div className="space-y-8">
            <header className="flex justify-between items-start border-b border-admin-dark-border pb-6">
              <div>
                <h2 className="text-3xl font-bold text-white mb-1">{selectedClient.name}</h2>
                <div className="flex gap-4 text-sm text-admin-dark-text-secondary">
                  <span>📧 {selectedClient.email}</span>
                  {selectedClient.phone && <span>📱 {selectedClient.phone}</span>}
                </div>
              </div>
              <div className="text-right">
                <div className="text-sm text-admin-dark-text-secondary">Lifetime Value</div>
                <div className="text-3xl font-bold text-green-400">R{selectedClient.totalSpend.toFixed(2)}</div>
              </div>
            </header>

            <div className="grid grid-cols-3 gap-4">
              <div className="bg-admin-dark-bg/50 p-4 rounded-lg text-center">
                <div className="text-xs text-admin-dark-text-secondary uppercase tracking-wider">Total Visits</div>
                <div className="text-xl font-bold text-white mt-1">{selectedClient.visitCount}</div>
              </div>
              <div className="bg-admin-dark-bg/50 p-4 rounded-lg text-center">
                <div className="text-xs text-admin-dark-text-secondary uppercase tracking-wider">Last Seen</div>
                <div className="text-xl font-bold text-white mt-1">{new Date(selectedClient.lastVisit).toLocaleDateString()}</div>
              </div>
              <div className="bg-admin-dark-bg/50 p-4 rounded-lg text-center">
                <div className="text-xs text-admin-dark-text-secondary uppercase tracking-wider">Payment Pref</div>
                <div className="text-xl font-bold text-white mt-1 capitalize">{selectedClient.preferredPayment}</div>
              </div>
            </div>

            <div>
              <h3 className="text-lg font-bold text-white mb-4">Booking History</h3>
              <div className="bg-admin-dark-bg/30 rounded-lg overflow-hidden">
                <table className="w-full text-sm text-left">
                  <thead className="bg-admin-dark-bg text-admin-dark-text-secondary uppercase text-xs">
                    <tr>
                      <th className="px-4 py-3">Date</th>
                      <th className="px-4 py-3">Service/Note</th>
                      <th className="px-4 py-3">Status</th>
                      <th className="px-4 py-3">Paid</th>
                      <th className="px-4 py-3">Method</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-admin-dark-border">
                    {selectedClient.bookings.sort((a,b) => new Date(b.bookingDate).getTime() - new Date(a.bookingDate).getTime()).map(booking => (
                      <tr key={booking.id} className="hover:bg-white/5 transition-colors">
                        <td className="px-4 py-3 text-white">{new Date(booking.bookingDate).toLocaleDateString()}</td>
                        <td className="px-4 py-3 text-gray-300 max-w-xs truncate">{booking.message || 'No notes'}</td>
                        <td className="px-4 py-3">
                          <span className={`px-2 py-0.5 rounded text-xs font-bold capitalize ${
                            booking.status === 'completed' ? 'bg-green-500/20 text-green-300' :
                            booking.status === 'cancelled' ? 'bg-red-500/20 text-red-300' :
                            'bg-yellow-500/20 text-yellow-300'
                          }`}>
                            {booking.status}
                          </span>
                        </td>
                        <td className="px-4 py-3 text-white">
                          {booking.totalCost ? `R${booking.totalCost}` : '-'}
                        </td>
                        <td className="px-4 py-3 text-gray-300 capitalize">
                          {booking.paymentMethod || '-'}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        ) : (
          <div className="flex flex-col items-center justify-center h-full text-admin-dark-text-secondary">
            <IconClients className="w-16 h-16 mb-4 opacity-50" />
            <p>Select a client to view their detailed profile.</p>
          </div>
        )}
      </div>
    </div>
  );
};

