                    <label htmlFor="emailPublicKey" className="block text-sm font-semibold text-admin-dark-text-secondary mb-2">Public Key</label>
                    <input type="password" id="emailPublicKey" value={settings.emailPublicKey} onChange={handleInputChange} className="w-full bg-admin-dark-bg border border-admin-dark-border rounded-lg p-3 text-admin-dark-text outline-none focus:ring-2 focus:ring-admin-dark-primary transition" />
                </div>
            </div>
        </section>

        <div className="flex items-center gap-4 pt-4 border-t border-admin-dark-border">
            <button type="submit" disabled={isLoading} className="bg-admin-dark-primary text-white px-8 py-3 rounded-lg font-bold hover:opacity-90 transition-opacity disabled:opacity-50"> {isLoading ? 'Saving...' : 'Save Changes'} </button>
            {savedMessage && <span className="text-green-400 text-sm" role="status">{savedMessage}</span>}
        </div>
      </form>

      {/* ... Backup and Danger Zone sections ... */}
    </div>
  );
};

