  // --- PUBLIC DATA FETCHING ---
  useEffect(() => {
    const unsubscribers: (() => void)[] = [];

    try {
      // Subscribe to settings document
      const unsubSettings = dbSubscribeToDoc("settings", "main", (settings: any) => {
          if (settings) {
            setCompanyName(settings.companyName || 'Die Bos Salon');
            setLogoUrl(settings.logoUrl || 'https://i.ibb.co/gLSThX4v/unnamed-removebg-preview.png');
            setAboutUsImageUrl(settings.aboutUsImageUrl || 'https://picsum.photos/seed/nail-artist/500/500');
