            setShowroomDescription(settings.showroomDescription || "Browse our collection of hand-painted designs and natural treatments.");
            setHeroTattooGunImageUrl(settings.heroTattooGunImageUrl || 'https://i.ibb.co/8DFd4pt7/unnamed-1.jpg');
