    if (!user) {
      setBookings([]);
      setExpenses([]);
      setInventory([]);
      return;
    }

    const unsubscribers: (() => void)[] = [];
    try {
        unsubscribers.push(dbSubscribeToCollection('bookings', (data) => setBookings(data)));
