// --- Inventory Manager Sub-Component ---
// To keep the file size manageable and logic clean, I'll define the Inventory Manager UI here within the Financials context
// since the prompt asked for "redo entire financials system".

const InventoryTab = ({ 
    inventory, onAdd, onUpdate, onDelete 
}: { 
    inventory: InventoryItem[], 
    onAdd: (i: any) => Promise<void>, 
    onUpdate: (i: any) => Promise<void>, 
    onDelete: (id: string) => Promise<void> 
}) => {
    const [isAdding, setIsAdding] = useState(false);
    const [formData, setFormData] = useState<Partial<InventoryItem>>({});

    const totalValue = inventory.reduce((sum, item) => sum + (item.quantity * item.unitCost), 0);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (formData.id) {
            await onUpdate(formData);
        } else {
            await onAdd(formData);
        }
        setIsAdding(false);
        setFormData({});
    };

    const handleEdit = (item: InventoryItem) => {
        setFormData(item);
        setIsAdding(true);
    };

    const inputClasses = "w-full bg-admin-dark-bg border border-admin-dark-border rounded-lg p-2 text-admin-dark-text focus:ring-2 focus:ring-admin-dark-primary outline-none";

    return (
        <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="bg-admin-dark-bg/50 p-4 rounded-lg border border-admin-dark-border">
                    <h4 className="text-admin-dark-text-secondary text-sm">Total Stock Value</h4>
                    <p className="text-2xl font-bold text-blue-400">R{totalValue.toFixed(2)}</p>
                </div>
                <div className="bg-admin-dark-bg/50 p-4 rounded-lg border border-admin-dark-border">
                    <h4 className="text-admin-dark-text-secondary text-sm">Total Items</h4>
                    <p className="text-2xl font-bold text-white">{inventory.length}</p>
                </div>
                <div className="bg-admin-dark-bg/50 p-4 rounded-lg border border-admin-dark-border">
                    <h4 className="text-admin-dark-text-secondary text-sm">Low Stock Alerts</h4>
                    <p className="text-2xl font-bold text-red-400">{inventory.filter(i => i.quantity <= i.minStockLevel).length}</p>
                </div>
            </div>

            <div className="flex justify-between items-center">
                <h3 className="text-lg font-bold text-white">Inventory Items</h3>
                <button onClick={() => { setFormData({}); setIsAdding(!isAdding); }} className="bg-admin-dark-primary text-white px-4 py-2 rounded-lg text-sm font-bold">
                    {isAdding ? 'Cancel' : '+ Add Item'}
                </button>
            </div>

            {isAdding && (
                <form onSubmit={handleSubmit} className="bg-black/20 p-6 rounded-lg border border-admin-dark-border animate-fade-in grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    <input className={inputClasses} placeholder="Product Name" value={formData.productName || ''} onChange={e => setFormData({...formData, productName: e.target.value})} required />
                    <input className={inputClasses} placeholder="Brand" value={formData.brand || ''} onChange={e => setFormData({...formData, brand: e.target.value})} />
                    <input className={inputClasses} placeholder="Category" value={formData.category || ''} onChange={e => setFormData({...formData, category: e.target.value})} />
                    <input className={inputClasses} type="number" placeholder="Quantity" value={formData.quantity || ''} onChange={e => setFormData({...formData, quantity: parseFloat(e.target.value)})} required />
                    <input className={inputClasses} type="number" placeholder="Min Stock Level" value={formData.minStockLevel || ''} onChange={e => setFormData({...formData, minStockLevel: parseFloat(e.target.value)})} required />
                    <input className={inputClasses} type="number" step="0.01" placeholder="Unit Cost (R)" value={formData.unitCost || ''} onChange={e => setFormData({...formData, unitCost: parseFloat(e.target.value)})} required />
                    <input className={inputClasses} placeholder="Supplier" value={formData.supplier || ''} onChange={e => setFormData({...formData, supplier: e.target.value})} />
                    <div className="md:col-span-2 lg:col-span-3 flex justify-end">
                        <button type="submit" className="bg-green-600 text-white px-6 py-2 rounded-lg font-bold">Save Item</button>
                    </div>
                </form>
            )}

            <div className="overflow-x-auto">
                <table className="w-full text-sm text-left">
                    <thead className="bg-admin-dark-bg text-admin-dark-text-secondary uppercase text-xs">
                        <tr>
                            <th className="px-4 py-3">Product</th>
                            <th className="px-4 py-3">Brand</th>
                            <th className="px-4 py-3">Stock</th>
                            <th className="px-4 py-3">Value</th>
                            <th className="px-4 py-3">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-admin-dark-border">
                        {inventory.map(item => (
                            <tr key={item.id} className="hover:bg-white/5">
                                <td className="px-4 py-3 font-semibold text-white">{item.productName}</td>
                                <td className="px-4 py-3 text-gray-400">{item.brand}</td>
                                <td className="px-4 py-3">
                                    <span className={`${item.quantity <= item.minStockLevel ? 'text-red-400 font-bold' : 'text-green-400'}`}>
                                        {item.quantity}
                                    </span>
                                </td>
                                <td className="px-4 py-3 text-white">R{(item.quantity * item.unitCost).toFixed(2)}</td>
                                <td className="px-4 py-3 flex gap-2">
                                    <button onClick={() => handleEdit(item)} className="text-blue-400 hover:text-blue-300">Edit</button>
                                    <button onClick={() => onDelete(item.id)} className="text-red-400 hover:text-red-300">Delete</button>
