interface FinancialsManagerProps {
    bookings: Booking[];
    expenses: Expense[];
    inventory: InventoryItem[];
    // CRUD
    onAddExpense: (e: any) => Promise<void>;
    onUpdateExpense: (e: any) => Promise<void>;
    onDeleteExpense: (id: string) => Promise<void>;
    onAddInventoryItem: (i: any) => Promise<void>;
    onUpdateInventoryItem: (i: any) => Promise<void>;
    onDeleteInventoryItem: (id: string) => Promise<void>;
    // Settings
    taxEnabled: boolean;
    vatPercentage: number;
    startTour: (key: any) => void;
}

const FinancialsManager: React.FC<FinancialsManagerProps> = (props) => {
    const [tab, setTab] = useState<'overview' | 'inventory' | 'expenses'>('overview');
    const [year, setYear] = useState(new Date().getFullYear());

    // Overview Calculations
    const completedBookings = props.bookings.filter(b => b.status === 'completed' && new Date(b.bookingDate).getFullYear() === year);
    const yearlyExpenses = props.expenses.filter(e => new Date(e.date).getFullYear() === year);

    const grossIncome = completedBookings.reduce((sum, b) => sum + (b.totalCost || 0), 0);
    const totalExpenseAmount = yearlyExpenses.reduce((sum, e) => sum + e.amount, 0);

    // Tax Logic
    const vatAmount = props.taxEnabled ? (grossIncome * (props.vatPercentage / 100)) : 0;
    const netIncome = grossIncome - vatAmount - totalExpenseAmount;

    // Expense Form State
    const [newExpense, setNewExpense] = useState<Partial<Expense>>({ date: new Date().toISOString().split('T')[0], category: 'Supplies' });

    const handleAddExpense = async (e: React.FormEvent) => {
        e.preventDefault();
        await props.onAddExpense(newExpense);
        setNewExpense({ date: new Date().toISOString().split('T')[0], category: 'Supplies', amount: 0, description: '' });
    };

    return (
        <div className="bg-admin-dark-card border border-admin-dark-border rounded-xl shadow-lg p-6">
            <header className="flex flex-col sm:flex-row justify-between items-center mb-8 gap-4">
                <div className="flex items-center gap-4">
                    <h2 className="text-2xl font-bold text-white">Financial Hub</h2>
                    <div className="bg-admin-dark-bg rounded-lg p-1 flex gap-1">
                        <button onClick={() => setTab('overview')} className={`px-4 py-1.5 rounded-md text-sm font-bold transition-colors ${tab === 'overview' ? 'bg-admin-dark-primary text-white' : 'text-gray-400 hover:text-white'}`}>Overview</button>
                        <button onClick={() => setTab('inventory')} className={`px-4 py-1.5 rounded-md text-sm font-bold transition-colors ${tab === 'inventory' ? 'bg-admin-dark-primary text-white' : 'text-gray-400 hover:text-white'}`}>Inventory</button>
                        <button onClick={() => setTab('expenses')} className={`px-4 py-1.5 rounded-md text-sm font-bold transition-colors ${tab === 'expenses' ? 'bg-admin-dark-primary text-white' : 'text-gray-400 hover:text-white'}`}>Expenses</button>
                    </div>
                </div>
                {tab === 'overview' && (
                    <select value={year} onChange={(e) => setYear(parseInt(e.target.value))} className="bg-admin-dark-bg border border-admin-dark-border text-white rounded-lg px-3 py-1">
                        {[2023, 2024, 2025, 2026].map(y => <option key={y} value={y}>{y}</option>)}
                    </select>
                )}
            </header>

            {tab === 'overview' && (
                <div className="space-y-8 animate-fade-in">
                    {/* KPI Cards */}
                    <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                        <div className="bg-admin-dark-bg/50 p-4 rounded-lg border border-admin-dark-border">
                            <h4 className="text-gray-400 text-sm mb-1">Gross Income</h4>
                            <p className="text-2xl font-bold text-green-400">R{grossIncome.toFixed(2)}</p>
                        </div>
                        <div className="bg-admin-dark-bg/50 p-4 rounded-lg border border-admin-dark-border">
                            <h4 className="text-gray-400 text-sm mb-1">Expenses</h4>
                            <p className="text-2xl font-bold text-red-400">R{totalExpenseAmount.toFixed(2)}</p>
                        </div>
                        {props.taxEnabled && (
                            <div className="bg-admin-dark-bg/50 p-4 rounded-lg border border-admin-dark-border">
                                <h4 className="text-gray-400 text-sm mb-1">VAT ({props.vatPercentage}%)</h4>
                                <p className="text-2xl font-bold text-yellow-400">R{vatAmount.toFixed(2)}</p>
                            </div>
                        )}
                        <div className="bg-admin-dark-bg/50 p-4 rounded-lg border border-admin-dark-border">
                            <h4 className="text-gray-400 text-sm mb-1">Net Profit</h4>
                            <p className={`text-2xl font-bold ${netIncome >= 0 ? 'text-blue-400' : 'text-red-500'}`}>R{netIncome.toFixed(2)}</p>
                        </div>
                    </div>

                    {/* Chart */}
                    <YearlyProfitChart bookings={props.bookings} expenses={props.expenses} selectedYear={year} />
                </div>
            )}

            {tab === 'inventory' && (
                <div className="animate-fade-in">
                    <InventoryTab 
                        inventory={props.inventory} 
                        onAdd={props.onAddInventoryItem} 
                        onUpdate={props.onUpdateInventoryItem} 
                        onDelete={props.onDeleteInventoryItem} 
                    />
                </div>
            )}

            {tab === 'expenses' && (
                <div className="animate-fade-in space-y-6">
                    {/* Add Expense Form */}
                    <form onSubmit={handleAddExpense} className="bg-black/20 p-4 rounded-lg border border-admin-dark-border grid grid-cols-1 md:grid-cols-4 gap-4">
                        <input type="date" value={newExpense.date} onChange={e => setNewExpense({...newExpense, date: e.target.value})} className="bg-admin-dark-bg border border-admin-dark-border rounded p-2 text-white" style={{colorScheme:'dark'}} required/>
                        <select value={newExpense.category} onChange={e => setNewExpense({...newExpense, category: e.target.value as any})} className="bg-admin-dark-bg border border-admin-dark-border rounded p-2 text-white">
                            <option>Supplies</option><option>Rent</option><option>Stock</option><option>Marketing</option><option>Other</option>
                        </select>
                        <input type="text" placeholder="Description" value={newExpense.description || ''} onChange={e => setNewExpense({...newExpense, description: e.target.value})} className="bg-admin-dark-bg border border-admin-dark-border rounded p-2 text-white" required/>
                        <div className="flex gap-2">
                            <input type="number" placeholder="Amount" value={newExpense.amount || ''} onChange={e => setNewExpense({...newExpense, amount: parseFloat(e.target.value)})} className="bg-admin-dark-bg border border-admin-dark-border rounded p-2 text-white w-full" step="0.01" required/>
                            <button type="submit" className="bg-red-600 text-white px-4 rounded font-bold hover:bg-red-700">+</button>
                        </div>
                    </form>

                    {/* Expense List */}
                    <div className="overflow-hidden rounded-lg border border-admin-dark-border">
                        <table className="w-full text-sm text-left">
                            <thead className="bg-admin-dark-bg text-gray-400 uppercase text-xs">
                                <tr>
                                    <th className="px-4 py-3">Date</th>
                                    <th className="px-4 py-3">Category</th>
                                    <th className="px-4 py-3">Description</th>
                                    <th className="px-4 py-3">Amount</th>
                                    <th className="px-4 py-3"></th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-admin-dark-border bg-admin-dark-bg/30">
                                {props.expenses.sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()).map(exp => (
                                    <tr key={exp.id} className="hover:bg-white/5">
                                        <td className="px-4 py-3 text-white">{new Date(exp.date).toLocaleDateString()}</td>
                                        <td className="px-4 py-3 text-gray-400"><span className="bg-gray-700/50 px-2 py-1 rounded text-xs">{exp.category}</span></td>
                                        <td className="px-4 py-3 text-gray-300">{exp.description}</td>
                                        <td className="px-4 py-3 text-red-400 font-mono font-bold">R{exp.amount.toFixed(2)}</td>
                                        <td className="px-4 py-3 text-right">
                                            <button onClick={() => props.onDeleteExpense(exp.id)} className="text-red-500 hover:text-red-300">&times;</button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}
        </div>
    );
};

