                            <select name="status" value={formData.status} onChange={handleChange} required className={selectClasses} style={{backgroundImage: `url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' fill='none' viewBox='0 0 20 20'%3e%3cpath stroke='%234e342e' stroke-linecap='round' stroke-linejoin='round' stroke-width='1.5' d='M6 8l4 4 4-4'/%3e%3c/svg%3e")`, backgroundPosition: 'right 0.5rem center', backgroundSize: '1.5em 1.5em'}}>
                                <option value="pending">Pending</option>
                                <option value="confirmed">Confirmed</option>
                                <option value="completed">Completed</option>
                                <option value="cancelled">Cancelled</option>
                            </select>
                        </div>
                    </div>
                    <div>
                         <label className="block text-sm font-semibold mb-2 text-admin-dark-text-secondary">Description / Message</label>
                         <textarea name="message" value={formData.message} onChange={handleChange} rows={3} className={inputClasses}></textarea>
                    </div>
                    <div className="border-t border-admin-dark-border pt-6">
                        <h3 className="text-lg font-semibold text-admin-dark-text mb-4">Financials & Payment</h3>
                        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                           <div>
                                <label className="block text-sm font-semibold mb-2 text-admin-dark-text-secondary">Total Cost (R)</label>
                                <input type="number" name="totalCost" value={formData.totalCost || ''} onChange={handleChange} step="0.01" className={inputClasses}/>
                           </div>
                           <div>
                                <label className="block text-sm font-semibold mb-2 text-admin-dark-text-secondary">Amount Paid (R)</label>
                                <input type="number" name="amountPaid" value={formData.amountPaid || ''} onChange={handleChange} step="0.01" className={inputClasses}/>
                           </div>
                           <div>
                                <label className="block text-sm font-semibold mb-2 text-admin-dark-text-secondary">Payment Method</label>
                                <select name="paymentMethod" value={formData.paymentMethod || 'cash'} onChange={handleChange} className={selectClasses} style={{backgroundImage: `url("data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' fill='none' viewBox='0 0 20 20'%3e%3cpath stroke='%234e342e' stroke-linecap='round' stroke-linejoin='round' stroke-width='1.5' d='M6 8l4 4 4-4'/%3e%3c/svg%3e")`, backgroundPosition: 'right 0.5rem center', backgroundSize: '1.5em 1.5em'}}>
                                    <option value="cash">Cash</option>
