interface PortfolioManagerProps {
  portfolioData: PortfolioItem[];
  onAddPortfolioItem: (item: Omit<PortfolioItem, 'id'>) => Promise<void>;
  onUpdatePortfolioItem: (item: PortfolioItem) => Promise<void>;
  onDeletePortfolioItem: (id: string) => Promise<void>;
  startTour: (tourKey: 'art') => void;
}

const PortfolioManager: React.FC<PortfolioManagerProps> = ({
  portfolioData, onAddPortfolioItem, onUpdatePortfolioItem, onDeletePortfolioItem, startTour
}) => {
    const [editingItem, setEditingItem] = useState<PortfolioItem | null>(null);
    const [isAddingNew, setIsAddingNew] = useState(false);

    const handleSaveItem = async (itemData: any) => {
        try {
            const { primaryImage, galleryImages, videoFile, ...restOfData } = itemData;

            const primaryImageUrl = primaryImage instanceof File ? await dbUploadFile(primaryImage, 'portfolio') : primaryImage;

            const galleryImageUrls = await Promise.all(
                (galleryImages || []).map((img: string | File) =>
                    img instanceof File ? dbUploadFile(img, 'portfolio') : Promise.resolve(img)
                )
            );

            const videoUrl = videoFile instanceof File ? await dbUploadFile(videoFile, 'portfolio', 'videos/') : videoFile ? itemData.videoData : undefined;

            const finalData = { ...restOfData, primaryImage: primaryImageUrl, galleryImages: galleryImageUrls, videoData: videoUrl };

            if (isAddingNew) {
                const { id, ...newItemData } = finalData;
                await onAddPortfolioItem(newItemData);
            } else {
                await onUpdatePortfolioItem(finalData as PortfolioItem);
            }
        } catch (error) {
            console.error("Failed to save portfolio item:", error);
            alert("Error saving item. Check the console for details.");
        } finally {
            setEditingItem(null);
            setIsAddingNew(false);
        }
    };

    const handleAddNewItem = () => {
        setEditingItem({} as PortfolioItem); // Use empty object for form
        setIsAddingNew(true);
    };

    const handleDeleteItem = async (id: string) => {
        if (window.confirm('Are you sure you want to delete this art piece? This will remove it from the database permanently.')) {
            await onDeletePortfolioItem(id);
        }
    };

    const handleToggleFeature = async (item: PortfolioItem) => {
        await onUpdatePortfolioItem({ ...item, featured: !item.featured });
    };

    return (
        <div className="bg-admin-dark-card border border-admin-dark-border rounded-xl shadow-lg p-6 space-y-8">
            <header className="flex items-center gap-3">
                <h2 className="text-xl font-bold text-white">Portfolio Management</h2>
                 <button onClick={() => startTour('art')} className="p-1.5 text-admin-dark-text-secondary hover:text-white hover:bg-white/10 rounded-full transition-colors" aria-label="Start Art Tour">
                    <span>🎓</span>
                </button>
            </header>

            <div>
                <header className="flex flex-col sm:flex-row justify-between sm:items-center mb-6 gap-4">
                    <div>
                        <h3 className="text-xl font-bold text-white">Portfolio Items</h3>
                        <p className="text-sm text-admin-dark-text-secondary mt-1">Manage individual art pieces with stories. Featured items appear on the homepage.</p>
                    </div>
                    {!(isAddingNew || editingItem) && (
                        <button data-tour-id="add-new-item-button" onClick={handleAddNewItem} className="flex items-center gap-2 bg-admin-dark-primary text-white px-4 py-2 rounded-lg font-bold text-sm hover:opacity-90 transition-opacity">
                            <PlusIcon className="w-5 h-5"/>
                            Add New Item
                        </button>
                    )}
                </header>

                {/* Updated Grid Layout */}
                <div data-tour-id="portfolio-item-list" className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                    {(isAddingNew || editingItem) && 
                        <div className="col-span-full">
                            <PortfolioItemEditForm 
                                initialItem={editingItem || {}} 
                                onSave={handleSaveItem} 
                                onCancel={() => { setEditingItem(null); setIsAddingNew(false); }} 
                                isAddingNew={isAddingNew}
                            />
                        </div>
                    }

                    {!editingItem && !isAddingNew && portfolioData.map(item => (
                        <div key={item.id} className="bg-admin-dark-bg/50 border border-admin-dark-border rounded-lg p-4 flex flex-col justify-between gap-4 hover:border-admin-dark-primary/30 transition-colors">
                            <div className="flex items-start gap-4">
                                <img src={item.primaryImage} alt={item.title} className="w-16 h-16 object-cover rounded-lg flex-shrink-0 shadow-sm"/>
                                <div className="overflow-hidden">
                                    <p className="font-semibold text-white truncate text-sm">{item.title}</p>
                                    <p className="text-xs text-admin-dark-text-secondary truncate mt-1">{item.story}</p>
                                    {item.videoData && <span className="text-[10px] uppercase tracking-wider font-bold text-blue-400 mt-1 block">Video</span>}
                                </div>
                            </div>
                            <div className="flex justify-between items-center border-t border-admin-dark-border pt-3 mt-auto">
                                <div data-tour-id="feature-toggle" className="flex items-center gap-2">
                                    <button onClick={() => handleToggleFeature(item)} className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors ${item.featured ? 'bg-admin-dark-primary' : 'bg-gray-600'}`}>
                                        <span className={`inline-block h-3 w-3 transform rounded-full bg-white transition-transform ${item.featured ? 'translate-x-5' : 'translate-x-1'}`}/>
                                    </button>
                                    <span className="text-xs text-admin-dark-text-secondary">Feature</span>
                                </div>
                                <div className="flex gap-1 text-admin-dark-text-secondary">
                                    <button onClick={() => { setIsAddingNew(false); setEditingItem(item); }} className="p-1.5 hover:bg-white/10 rounded-full hover:text-white transition-colors" aria-label={`Edit ${item.title}`}>
                                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.5L14.732 3.732z"></path></svg>
                                    </button>
                                    <button onClick={() => handleDeleteItem(item.id)} className="p-1.5 hover:bg-red-500/20 text-red-500 hover:text-red-400 rounded-full transition-colors" aria-label={`Delete ${item.title}`}>
                                        <TrashIcon className="w-4 h-4"/>
                                    </button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

export default PortfolioManager;

import React, { useState } from 'react';
import { SpecialItem } from '../../App';
import { dbUploadFile } from '../../utils/dbAdapter';
import PlusIcon from '../../components/icons/PlusIcon';
import TrashIcon from '../../components/icons/TrashIcon';
import PencilIcon from '../../components/icons/PencilIcon';

const SpecialForm = ({
  initialItem,
  onSave,
  onCancel,
}: {
  initialItem: Partial<SpecialItem>;
  onSave: (item: any) => Promise<void>;
  onCancel: () => void;
}) => {
  const [formData, setFormData] = useState(initialItem);
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState(initialItem.imageUrl || '');
  const [loading, setLoading] = useState(false);

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setImageFile(e.target.files[0]);
      setPreviewUrl(URL.createObjectURL(e.target.files[0]));
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    await onSave({ ...formData, imageFile });
    setLoading(false);
  };

  const inputClasses = "w-full bg-admin-dark-bg border border-admin-dark-border rounded-lg p-2.5 text-admin-dark-text focus:ring-2 focus:ring-admin-dark-primary outline-none transition";

  return (
    <form onSubmit={handleSubmit} className="bg-black/20 border border-admin-dark-border rounded-lg p-6 mb-6 col-span-full">
      <h3 className="text-xl font-bold text-white mb-4">{initialItem.id ? 'Edit Special' : 'Add New Special'}</h3>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-semibold mb-2 text-admin-dark-text-secondary">Title</label>
            <input 
              type="text" 
              value={formData.title || ''} 
              onChange={e => setFormData({...formData, title: e.target.value})}
              className={inputClasses} 
              required
            />
          </div>
          <div>
            <label className="block text-sm font-semibold mb-2 text-admin-dark-text-secondary">Description</label>
            <textarea 
              value={formData.description || ''} 
              onChange={e => setFormData({...formData, description: e.target.value})}
              className={inputClasses} 
              rows={3}
              required
            />
          </div>
          <div className="flex gap-4">
             <div className="flex-1">
                <label className="block text-sm font-semibold mb-2 text-admin-dark-text-secondary">Price (R)</label>
                <input 
                  type="number" 
                  value={formData.price || ''} 
                  onChange={e => setFormData({...formData, price: parseFloat(e.target.value)})}
                  className={inputClasses} 
                  step="0.01"
                  required
                />
             </div>
             <div className="flex items-end pb-3">
               <label className="flex items-center space-x-2 cursor-pointer">
                 <input 
                    type="checkbox" 
                    checked={formData.active !== false} 
                    onChange={e => setFormData({...formData, active: e.target.checked})}
                    className="w-5 h-5 accent-admin-dark-primary rounded"
                 />
                 <span className="text-white font-semibold">Active</span>
               </label>
             </div>
          </div>
        </div>

        <div>
          <label className="block text-sm font-semibold mb-2 text-admin-dark-text-secondary">Image</label>
          <div className="border-2 border-dashed border-admin-dark-border rounded-lg p-4 text-center h-48 flex flex-col items-center justify-center relative overflow-hidden bg-admin-dark-bg/50">
            {previewUrl ? (
              <img src={previewUrl} alt="Preview" className="absolute inset-0 w-full h-full object-cover" />
            ) : (
              <span className="text-admin-dark-text-secondary">No image selected</span>
            )}
            <input type="file" accept="image/*" onChange={handleImageChange} className="absolute inset-0 opacity-0 cursor-pointer" />
          </div>
          <p className="text-xs text-admin-dark-text-secondary mt-2 text-center">Click to upload new image</p>
        </div>
      </div>

      <div className="flex justify-end gap-3 mt-6">
        <button type="button" onClick={onCancel} className="px-4 py-2 text-admin-dark-text-secondary hover:text-white transition-colors">Cancel</button>
        <button type="submit" disabled={loading} className="bg-admin-dark-primary text-white px-6 py-2 rounded-lg font-bold hover:bg-opacity-90 transition-opacity disabled:opacity-50">
          {loading ? 'Saving...' : 'Save Special'}
        </button>
      </div>
    </form>
  );
};

interface SpecialsManagerProps {
  specialsData: SpecialItem[];
  onAddSpecialItem: (item: Omit<SpecialItem, 'id'>) => Promise<void>;
  onUpdateSpecialItem: (item: SpecialItem) => Promise<void>;
  onDeleteSpecialItem: (id: string) => Promise<void>;
}

const SpecialsManager: React.FC<SpecialsManagerProps> = ({ specialsData, onAddSpecialItem, onUpdateSpecialItem, onDeleteSpecialItem }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [editingItem, setEditingItem] = useState<SpecialItem | null>(null);

  const handleSave = async (data: any) => {
    try {
      let imageUrl = data.imageUrl || '';
      if (data.imageFile) {
        imageUrl = await dbUploadFile(data.imageFile, 'specials');
      }

      const itemPayload = {
        title: data.title,
        description: data.description,
        price: data.price,
        active: data.active !== false, // Default to true if undefined
        imageUrl,
      };

      if (editingItem) {
        await onUpdateSpecialItem({ ...itemPayload, id: editingItem.id } as SpecialItem);
      } else {
        await onAddSpecialItem(itemPayload as any);
      }
      setIsAdding(false);
      setEditingItem(null);
    } catch (error) {
      console.error("Error saving special:", error);
      alert("Failed to save special.");
    }
  };

  const handleDelete = async (id: string) => {
    if(window.confirm("Are you sure you want to remove this special offer?")) {
      await onDeleteSpecialItem(id);
    }
  };

  return (
    <div className="bg-admin-dark-card border border-admin-dark-border rounded-xl shadow-lg p-6">
      <header className="flex justify-between items-center mb-8">
        <div>
          <h2 className="text-xl font-bold text-white">Public Specials</h2>
          <p className="text-sm text-admin-dark-text-secondary">Manage offers displayed on the "Seasonal Specials" section of your website.</p>
        </div>
        {!isAdding && !editingItem && (
          <button onClick={() => setIsAdding(true)} className="flex items-center gap-2 bg-admin-dark-primary text-white px-4 py-2 rounded-lg font-bold text-sm hover:opacity-90">
            <PlusIcon className="w-5 h-5" /> Add Special
          </button>
        )}
      </header>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">

        {(isAdding || editingItem) && (
            <SpecialForm 
            initialItem={editingItem || {}} 
            onSave={handleSave} 
            onCancel={() => { setIsAdding(false); setEditingItem(null); }} 
            />
        )}

        {specialsData.map(special => (
          <div key={special.id} className={`bg-admin-dark-bg/50 border ${special.active ? 'border-green-500/30' : 'border-red-500/30'} rounded-lg overflow-hidden flex flex-col hover:border-opacity-60 transition-colors`}>
            <div className="relative h-48">
              <img src={special.imageUrl} alt={special.title} className="w-full h-full object-cover" />
              <div className="absolute top-2 right-2 flex gap-2">
                <span className={`px-2 py-1 text-[10px] uppercase font-bold rounded text-white shadow-sm ${special.active ? 'bg-green-600' : 'bg-red-500'}`}>
                  {special.active ? 'Active' : 'Inactive'}
                </span>
              </div>
              <div className="absolute bottom-2 right-2 bg-black/70 text-white px-3 py-1 rounded-full text-xs font-bold backdrop-blur-sm">
                R{special.price}
              </div>
            </div>
            <div className="p-4 flex-grow">
              <h4 className="font-bold text-white text-md mb-1 line-clamp-1">{special.title}</h4>
              <p className="text-xs text-admin-dark-text-secondary line-clamp-3">{special.description}</p>
            </div>
            <div className="p-3 border-t border-admin-dark-border flex justify-end gap-2 bg-black/20">
              <button onClick={() => setEditingItem(special)} className="p-2 text-admin-dark-text-secondary hover:text-white hover:bg-white/10 rounded-full transition-colors" title="Edit">
                <PencilIcon className="w-4 h-4" />
              </button>
              <button onClick={() => handleDelete(special.id)} className="p-2 text-red-400 hover:text-red-300 hover:bg-red-900/20 rounded-full transition-colors" title="Delete">
                <TrashIcon className="w-4 h-4" />
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default SpecialsManager;

