import React, { useState } from 'react';
import { InventoryItem } from '../../App';
import PlusIcon from '../../components/icons/PlusIcon';
import TrashIcon from '../../components/icons/TrashIcon';
import PencilIcon from '../../components/icons/PencilIcon';

interface InventoryManagerProps {
  inventory: InventoryItem[];
  onAddInventoryItem: (item: Omit<InventoryItem, 'id'>) => Promise<void>;
  onUpdateInventoryItem: (item: InventoryItem) => Promise<void>;
  onDeleteInventoryItem: (id: string) => Promise<void>;
  startTour: (tourKey: 'inventory') => void;
}

const InventoryManager: React.FC<InventoryManagerProps> = ({
  inventory,
  onAddInventoryItem,
  onUpdateInventoryItem,
  onDeleteInventoryItem,
  startTour
}) => {
  const [isAdding, setIsAdding] = useState(false);
  const [formData, setFormData] = useState<Partial<InventoryItem>>({});

  const totalValue = inventory.reduce((sum, item) => sum + (item.quantity * item.unitCost), 0);
  const lowStockItems = inventory.filter(i => i.quantity <= i.minStockLevel);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
        if (formData.id) {
            await onUpdateInventoryItem(formData as InventoryItem);
        } else {
            await onAddInventoryItem(formData as Omit<InventoryItem, 'id'>);
        }
        setIsAdding(false);
        setFormData({});
    } catch (error) {
        console.error("Error saving inventory item:", error);
        alert("Failed to save item.");
    }
  };

  const handleEdit = (item: InventoryItem) => {
    setFormData(item);
    setIsAdding(true);
  };

  const handleDelete = async (id: string) => {
      if(window.confirm("Are you sure you want to delete this item?")) {
          await onDeleteInventoryItem(id);
      }
  }

  const inputClasses = "w-full bg-admin-dark-bg border border-admin-dark-border rounded-lg p-2.5 text-admin-dark-text focus:ring-2 focus:ring-admin-dark-primary outline-none transition";

  return (
    <div className="bg-admin-dark-card border border-admin-dark-border rounded-xl shadow-lg p-6 space-y-8 h-full flex flex-col">
      <header className="flex flex-col sm:flex-row justify-between items-center gap-4 flex-shrink-0">
        <div className="flex items-center gap-3">
            <h2 className="text-xl font-bold text-white">Inventory Management</h2>
            <button onClick={() => startTour('inventory')} className="p-1.5 text-admin-dark-text-secondary hover:text-white hover:bg-white/10 rounded-full transition-colors" aria-label="Start Inventory Tour">
                <span>🎓</span>
            </button>
        </div>
        <button 
            data-tour-id="inventory-add-button"
            onClick={() => { setFormData({}); setIsAdding(!isAdding); }} 
            className="flex items-center gap-2 bg-admin-dark-primary text-white px-4 py-2 rounded-lg font-bold text-sm hover:opacity-90 transition-opacity"
        >
            <PlusIcon className="w-5 h-5" />
            {isAdding ? 'Cancel' : 'Add Item'}
        </button>
      </header>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 flex-shrink-0">
        <div className="bg-admin-dark-bg/50 p-4 rounded-lg border border-admin-dark-border">
            <h4 className="text-admin-dark-text-secondary text-sm font-semibold">Total Stock Value</h4>
            <p className="text-2xl font-bold text-blue-400 mt-1">R{totalValue.toFixed(2)}</p>
        </div>
        <div className="bg-admin-dark-bg/50 p-4 rounded-lg border border-admin-dark-border">
            <h4 className="text-admin-dark-text-secondary text-sm font-semibold">Total Items</h4>
            <p className="text-2xl font-bold text-white mt-1">{inventory.length}</p>
        </div>
        <div className="bg-admin-dark-bg/50 p-4 rounded-lg border border-admin-dark-border">
            <h4 className="text-admin-dark-text-secondary text-sm font-semibold">Low Stock Alerts</h4>
            <p className={`text-2xl font-bold mt-1 ${lowStockItems.length > 0 ? 'text-red-500' : 'text-green-500'}`}>
                {lowStockItems.length}
            </p>
        </div>
      </div>

      {/* Form */}
      {isAdding && (
        <form onSubmit={handleSubmit} className="bg-black/20 p-6 rounded-xl border border-admin-dark-border animate-fade-in flex-shrink-0">
            <h3 className="text-lg font-bold text-white mb-4">{formData.id ? 'Edit Item' : 'New Stock Item'}</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                <div className="col-span-1 md:col-span-2">
                    <label className="block text-xs font-bold text-admin-dark-text-secondary mb-1">Product Name</label>
                    <input className={inputClasses} placeholder="e.g. Black Ink" value={formData.productName || ''} onChange={e => setFormData({...formData, productName: e.target.value})} required />
                </div>
                <div>
                    <label className="block text-xs font-bold text-admin-dark-text-secondary mb-1">Brand</label>
                    <input className={inputClasses} placeholder="e.g. Dynamic" value={formData.brand || ''} onChange={e => setFormData({...formData, brand: e.target.value})} />
                </div>
                <div>
                    <label className="block text-xs font-bold text-admin-dark-text-secondary mb-1">Category</label>
                    <input className={inputClasses} placeholder="e.g. Inks" value={formData.category || ''} onChange={e => setFormData({...formData, category: e.target.value})} />
                </div>
                <div>
                    <label className="block text-xs font-bold text-admin-dark-text-secondary mb-1">Quantity</label>
                    <input className={inputClasses} type="number" placeholder="0" value={formData.quantity || ''} onChange={e => setFormData({...formData, quantity: parseFloat(e.target.value)})} required />
                </div>
                <div>
                    <label className="block text-xs font-bold text-admin-dark-text-secondary mb-1">Min Stock Level</label>
                    <input className={inputClasses} type="number" placeholder="5" value={formData.minStockLevel || ''} onChange={e => setFormData({...formData, minStockLevel: parseFloat(e.target.value)})} required />
                </div>
                <div>
                    <label className="block text-xs font-bold text-admin-dark-text-secondary mb-1">Unit Cost (R)</label>
                    <input className={inputClasses} type="number" step="0.01" placeholder="0.00" value={formData.unitCost || ''} onChange={e => setFormData({...formData, unitCost: parseFloat(e.target.value)})} required />
                </div>
                <div>
                    <label className="block text-xs font-bold text-admin-dark-text-secondary mb-1">Supplier</label>
                    <input className={inputClasses} placeholder="Supplier Name" value={formData.supplier || ''} onChange={e => setFormData({...formData, supplier: e.target.value})} />
                </div>
            </div>
            <div className="flex justify-end gap-3 mt-6">
                <button type="button" onClick={() => setIsAdding(false)} className="px-4 py-2 text-sm text-admin-dark-text-secondary hover:text-white transition-colors">Cancel</button>
                <button type="submit" className="bg-admin-dark-primary text-white px-6 py-2 rounded-lg font-bold text-sm hover:opacity-90">Save Item</button>
            </div>
        </form>
      )}

      {/* Table */}
      <div data-tour-id="inventory-list" className="flex-grow overflow-auto bg-admin-dark-bg/30 border border-admin-dark-border rounded-xl">
        <table className="w-full text-sm text-left">
            <thead className="bg-admin-dark-bg text-admin-dark-text-secondary uppercase text-xs sticky top-0 z-10 shadow-sm">
                <tr>
                    <th className="px-6 py-4 font-bold">Product</th>
                    <th className="px-6 py-4 font-bold">Brand</th>
                    <th className="px-6 py-4 font-bold">Category</th>
                    <th className="px-6 py-4 font-bold">Stock</th>
                    <th className="px-6 py-4 font-bold">Value</th>
                    <th className="px-6 py-4 font-bold text-right">Actions</th>
                </tr>
            </thead>
            <tbody className="divide-y divide-admin-dark-border">
                {inventory.length > 0 ? (
                    inventory.map(item => (
                        <tr key={item.id} className="hover:bg-white/5 transition-colors group">
                            <td className="px-6 py-4 font-semibold text-white">{item.productName}</td>
                            <td className="px-6 py-4 text-gray-400">{item.brand}</td>
                            <td className="px-6 py-4 text-gray-400">{item.category}</td>
                            <td className="px-6 py-4">
                                <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold ${item.quantity <= item.minStockLevel ? 'bg-red-500/20 text-red-400' : 'bg-green-500/20 text-green-400'}`}>
                                    {item.quantity}
                                    {item.quantity <= item.minStockLevel && <span className="ml-1 text-[10px]">⚠️</span>}
                                </span>
                            </td>
                            <td className="px-6 py-4 text-white font-mono">R{(item.quantity * item.unitCost).toFixed(2)}</td>
                            <td className="px-6 py-4">
                                <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                    <button onClick={() => handleEdit(item)} className="p-1.5 text-blue-400 hover:bg-blue-500/10 rounded transition-colors" title="Edit">
                                        <PencilIcon className="w-4 h-4" />
                                    </button>
                                    <button onClick={() => handleDelete(item.id)} className="p-1.5 text-red-400 hover:bg-red-500/10 rounded transition-colors" title="Delete">
                                        <TrashIcon className="w-4 h-4" />
                                    </button>
                                </div>
                            </td>
                        </tr>
                    ))
                ) : (
                    <tr>
                        <td colSpan={6} className="text-center py-12 text-admin-dark-text-secondary">
                            No items in inventory. Click "Add Item" to get started.
                        </td>
                    </tr>
                )}
            </tbody>
        </table>
      </div>
    </div>
  );
};

