                <div className="animate-fade-in space-y-6 flex-col flex h-full">
                    {/* Add Expense Form */}
                    <form onSubmit={handleAddExpense} className="bg-black/20 p-4 rounded-lg border border-admin-dark-border grid grid-cols-1 md:grid-cols-12 gap-4 flex-shrink-0">
                        <div className="md:col-span-2">
                            <input type="date" value={newExpense.date} onChange={e => setNewExpense({...newExpense, date: e.target.value})} className="w-full bg-admin-dark-bg border border-admin-dark-border rounded p-2 text-white text-sm" style={{colorScheme:'dark'}} required/>
                        </div>
                        <div className="md:col-span-2">
                            <select value={newExpense.category} onChange={e => setNewExpense({...newExpense, category: e.target.value as any})} className="w-full bg-admin-dark-bg border border-admin-dark-border rounded p-2 text-white text-sm">
                                <option>Supplies</option><option>Rent</option><option>Stock</option><option>Marketing</option><option>Other</option>
                            </select>
                        </div>
                        <div className="md:col-span-5">
                            <input type="text" placeholder="Description" value={newExpense.description || ''} onChange={e => setNewExpense({...newExpense, description: e.target.value})} className="w-full bg-admin-dark-bg border border-admin-dark-border rounded p-2 text-white text-sm" required/>
                        </div>
                        <div className="md:col-span-2">
                            <input type="number" placeholder="Amount" value={newExpense.amount || ''} onChange={e => setNewExpense({...newExpense, amount: parseFloat(e.target.value)})} className="w-full bg-admin-dark-bg border border-admin-dark-border rounded p-2 text-white text-sm" step="0.01" required/>
                        </div>
                        <div className="md:col-span-1">
                            <button type="submit" className="w-full bg-red-600 text-white p-2 rounded font-bold hover:bg-red-700 text-sm">+</button>
                        </div>
                    </form>

                    {/* Expense List */}
                    <div className="overflow-auto rounded-lg border border-admin-dark-border flex-grow bg-admin-dark-bg/30">
                        <table className="w-full text-sm text-left relative">
                            <thead className="bg-admin-dark-bg text-gray-400 uppercase text-xs sticky top-0 z-10 shadow-sm">
                                <tr>
                                    <th className="px-4 py-3">Date</th>
                                    <th className="px-4 py-3">Category</th>
                                    <th className="px-4 py-3">Description</th>
                                    <th className="px-4 py-3">Amount</th>
                                    <th className="px-4 py-3"></th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-admin-dark-border">
                                {props.expenses.sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()).map(exp => (
                                    <tr key={exp.id} className="hover:bg-white/5 transition-colors group">
                                        <td className="px-4 py-3 text-white">{new Date(exp.date).toLocaleDateString()}</td>
                                        <td className="px-4 py-3 text-gray-400"><span className="bg-gray-700/50 px-2 py-1 rounded text-xs">{exp.category}</span></td>
                                        <td className="px-4 py-3 text-gray-300">{exp.description}</td>
                                        <td className="px-4 py-3 text-red-400 font-mono font-bold">R{exp.amount.toFixed(2)}</td>
                                        <td className="px-4 py-3 text-right">
                                            <button onClick={() => props.onDeleteExpense(exp.id)} className="text-red-500 hover:text-red-300 opacity-0 group-hover:opacity-100 transition-opacity">&times;</button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}
        </div>
    );
};

export default FinancialsManager;
